TRUNCATE TABLE public.questions RESTART IDENTITY;

INSERT INTO public.questions (chapter, question_text, options, correct_answer) VALUES
-- ==========================================
-- BAB 1: Kepramukaan Dasar
-- ==========================================
(1, 'Siapakah penulis buku referensi Pramuka "Boyman"?', '["A. Tunas Kelapa","B. Reka","C. Andri Bob Sunardi","D. 14 Agustus"]', 'C. Andri Bob Sunardi'),
(1, 'Sifat kepramukaan yang penyelenggaraannya disesuaikan dengan keadaan dan kebutuhan masyarakat di negaranya adalah sifat...', '["A. Pramuka Garuda","B. Nasional","C. Kepramukaan","D. Masyarakat dan Organisasi"]', 'B. Nasional'),
(1, 'Kepramukaan dapat berlaku untuk siapa saja dan diselenggarakan di mana saja. Ini disebut sifat...', '["A. Universal","B. Purwa, Madya, Utama","C. Ramu, Rakit, Terap","D. Ki Hajar Dewantara"]', 'A. Universal'),
(1, 'Kepramukaan harus dapat mengembangkan rasa persaudaraan dan persahabatan antar sesama manusia. Ini adalah cerminan dari sifat...', '["A. Perindukan","B. Internasional","C. Pengabdian","D. Mula, Bantu, Tata"]', 'B. Internasional'),
(1, 'Fungsi kepramukaan bagi peserta didik (anak/pemuda) pada dasarnya adalah sebagai...', '["A. Sangga","B. Dwisatya dan Dwidarma","C. Permainan yang menarik","D. Tanda Kecakapan Umum"]', 'C. Permainan yang menarik'),
(1, 'Bagi orang dewasa, kepramukaan bukan lagi permainan, melainkan suatu tugas yang memerlukan keikhlasan. Ini adalah fungsi sebagai...', '["A. Dwisatya dan Dwidarma","B. Pengabdian","C. Kepramukaan","D. 14 Agustus"]', 'B. Pengabdian'),
(1, 'Kepramukaan berfungsi sebagai alat untuk memenuhi kebutuhan dan tujuan masyarakat. Ini adalah fungsi kepramukaan bagi...', '["A. Ing Ngarso Sung Tulodo","B. Pramuka","C. Trisatya dan Dasadarma","D. Masyarakat dan Organisasi"]', 'D. Masyarakat dan Organisasi'),
(1, 'Proses pendidikan di luar lingkungan sekolah dan keluarga dalam bentuk kegiatan menarik di alam terbuka disebut...', '["A. Ki Hajar Dewantara","B. Kepramukaan","C. Belajar sambil melakukan","D. Permainan yang menarik"]', 'B. Kepramukaan'),
(1, 'Orang-orang atau anggota yang mengikuti kegiatan dan tergabung di dalam organisasi kepanduan di Indonesia disebut...', '["A. Pramuka","B. Nasional","C. Belajar sambil melakukan","D. Reka"]', 'A. Pramuka'),
(1, 'Organisasi atau wadah resmi yang menyelenggarakan pendidikan kepramukaan di Indonesia adalah...', '["A. Ramu, Rakit, Terap","B. Purwa, Madya, Utama","C. Gerakan Pramuka","D. Internasional"]', 'C. Gerakan Pramuka'),
(1, 'Kepanjangan dari PRAMUKA adalah...', '["A. Praja Muda Karana","B. 14 Agustus 1961","C. Nasional","D. Masyarakat dan Organisasi"]', 'A. Praja Muda Karana'),
(1, 'Istilah Praja Muda Karana memiliki arti...', '["A. Tanda Kecakapan Khusus","B. Rakyat muda yang suka berkarya","C. Andri Bob Sunardi","D. Bunga Lily (Fleur-de-lis)"]', 'B. Rakyat muda yang suka berkarya'),
(1, 'Bapak Pramuka Indonesia adalah...', '["A. Pramuka Garuda","B. UU No. 12 Tahun 2010","C. Sri Sultan Hamengkubuwono IX","D. Satyaku Kudarmakan, Darmaku Kubaktikan"]', 'C. Sri Sultan Hamengkubuwono IX'),
(1, 'Bapak Pandu Dunia (Chief Scout of the World) adalah...', '["A. Lord Robert Baden Powell","B. Bunga Lily (Fleur-de-lis)","C. Tanda Kecakapan Khusus","D. Tunas Kelapa"]', 'A. Lord Robert Baden Powell'),
(1, 'Tujuan Gerakan Pramuka yang pertama adalah membentuk anggota pramuka agar memiliki kepribadian yang...', '["A. Tanda Kecakapan Umum","B. Lord Robert Baden Powell","C. Beriman, bertakwa, dan berakhlak mulia","D. Trisatya dan Dasadarma"]', 'C. Beriman, bertakwa, dan berakhlak mulia'),
(1, 'Tujuan Gerakan Pramuka yang kedua adalah agar anggota pramuka menjadi warga negara yang...', '["A. Sri Sultan Hamengkubuwono IX","B. Berjiwa Pancasila","C. Pramuka Garuda","D. Lord Robert Baden Powell"]', 'B. Berjiwa Pancasila'),
(1, 'Salah satu pilar metode kepramukaan adalah "Learning by Doing", yang artinya...', '["A. Pramuka Garuda","B. Belajar sambil melakukan","C. UU No. 12 Tahun 2010","D. Sri Sultan Hamengkubuwono IX"]', 'B. Belajar sambil melakukan'),
(1, 'Penggolongan usia Pramuka Siaga adalah...', '["A. 7 - 10 tahun","B. Bantara, Laksana","C. Pramuka Garuda","D. Bunga Lily (Fleur-de-lis)"]', 'A. 7 - 10 tahun'),
(1, 'Penggolongan usia Pramuka Penggalang adalah...', '["A. Tunas Kelapa","B. 11 - 15 tahun","C. Ki Hajar Dewantara","D. Lord Robert Baden Powell"]', 'B. 11 - 15 tahun'),
(1, 'Penggolongan usia Pramuka Penegak adalah...', '["A. Lord Robert Baden Powell","B. 21 - 25 tahun","C. 16 - 20 tahun","D. 11 - 15 tahun"]', 'C. 16 - 20 tahun'),
(1, 'Penggolongan usia Pramuka Pandega adalah...', '["A. Dwisatya dan Dwidarma","B. Ing Ngarso Sung Tulodo","C. Praja Muda Karana","D. 21 - 25 tahun"]', 'D. 21 - 25 tahun'),
(1, 'Kode Kehormatan bagi Pramuka Siaga terdiri dari...', '["A. Pengabdian","B. Dwisatya dan Dwidarma","C. Soenardjo Atmodipuro","D. Pasukan"]', 'B. Dwisatya dan Dwidarma'),
(1, 'Kode Kehormatan bagi Pramuka Penggalang, Penegak, dan Pandega terdiri dari...', '["A. Dwisatya dan Dwidarma","B. Trisatya dan Dasadarma","C. Berjiwa Pancasila","D. Pengabdian"]', 'B. Trisatya dan Dasadarma'),
(1, 'Sistem Pendidikan Kepramukaan menggunakan Sistem Among yang digagas oleh...', '["A. Sri Sultan Hamengkubuwono IX","B. Perindukan","C. Ki Hajar Dewantara","D. Nasional"]', 'C. Ki Hajar Dewantara'),
(1, 'Semboyan Sistem Among di depan memberikan teladan adalah...', '["A. Ing Ngarso Sung Tulodo","B. Dwisatya dan Dwidarma","C. Praja Muda Karana","D. Beriman, bertakwa, dan berakhlak mulia"]', 'A. Ing Ngarso Sung Tulodo'),
(1, 'Semboyan Sistem Among di tengah membangun kemauan adalah...', '["A. 7 - 10 tahun","B. Ing Madyo Mangun Karso","C. Andri Bob Sunardi","D. Masyarakat dan Organisasi"]', 'B. Ing Madyo Mangun Karso'),
(1, 'Semboyan Sistem Among di belakang memberikan dorongan adalah...', '["A. Masyarakat dan Organisasi","B. Tanda Kecakapan Khusus","C. Tut Wuri Handayani","D. Pengabdian"]', 'C. Tut Wuri Handayani'),
(1, 'Satuan terkecil dalam Pramuka Siaga disebut...', '["A. Soenardjo Atmodipuro","B. Berjiwa Pancasila","C. Barung","D. Trisatya dan Dasadarma"]', 'C. Barung'),
(1, 'Satuan terkecil dalam Pramuka Penggalang disebut...', '["A. Trisatya dan Dasadarma","B. Regu","C. Ramu, Rakit, Terap","D. Ki Hajar Dewantara"]', 'B. Regu'),
(1, 'Satuan terkecil dalam Pramuka Penegak disebut...', '["A. 14 Agustus","B. Kepramukaan","C. Reka","D. Sangga"]', 'D. Sangga'),
(1, 'Satuan terkecil dalam Pramuka Pandega disebut...', '["A. Reka","B. Pramuka Garuda","C. Internasional","D. Dwisatya dan Dwidarma"]', 'A. Reka'),
(1, 'Kumpulan dari beberapa Barung dalam Siaga disebut...', '["A. TKU dan TKK","B. Perindukan","C. Berjiwa Pancasila","D. Gerakan Pramuka"]', 'B. Perindukan'),
(1, 'Kumpulan dari beberapa Regu dalam Penggalang disebut...', '["A. Barung","B. Pasukan","C. Pramuka Garuda","D. Bunga Lily (Fleur-de-lis)"]', 'B. Pasukan'),
(1, 'Kumpulan dari beberapa Sangga dalam Penegak disebut...', '["A. Ambalan","B. Pramuka Garuda","C. Racana","D. Berjiwa Pancasila"]', 'A. Ambalan'),
(1, 'Wadah pembinaan Pramuka Pandega di Perguruan Tinggi disebut...', '["A. Soenardjo Atmodipuro","B. Racana","C. Internasional","D. Perindukan"]', 'B. Racana'),
(1, 'Tanda kecakapan dalam kepramukaan dibagi menjadi dua, yaitu...', '["A. TKU dan TKK","B. Barung","C. Tanda Kecakapan Khusus","D. Ing Madyo Mangun Karso"]', 'A. TKU dan TKK'),
(1, 'TKU singkatan dari...', '["A. Praja Muda Karana","B. Tanda Kecakapan Umum","C. Regu","D. Rakyat muda yang suka berkarya"]', 'B. Tanda Kecakapan Umum'),
(1, 'TKK singkatan dari...', '["A. Tanda Kecakapan Khusus","B. TKU dan TKK","C. Ing Madyo Mangun Karso","D. Nasional"]', 'A. Tanda Kecakapan Khusus'),
(1, 'Tingkatan TKU pada Pramuka Siaga adalah...', '["A. Pengabdian","B. Mula, Bantu, Tata","C. Pramuka Garuda","D. Bunga Lily (Fleur-de-lis)"]', 'B. Mula, Bantu, Tata'),
(1, 'Tingkatan TKU pada Pramuka Penggalang adalah...', '["A. Ramu, Rakit, Terap","B. Pramuka Garuda","C. Mula, Bantu, Tata","D. Gerakan Pramuka"]', 'A. Ramu, Rakit, Terap'),
(1, 'Tingkatan TKU pada Pramuka Penegak adalah...', '["A. Bantara, Laksana","B. Permainan yang menarik","C. Tunas Kelapa","D. Pramuka Garuda"]', 'A. Bantara, Laksana'),
(1, 'Tingkatan TKK (Tanda Kecakapan Khusus) dibagi menjadi 3 tingkatan, yaitu...', '["A. Kepramukaan","B. Pasukan","C. Purwa, Madya, Utama","D. Nasional"]', 'C. Purwa, Madya, Utama'),
(1, 'Lambang Gerakan Pramuka Indonesia adalah...', '["A. Tunas Kelapa","B. Tanda Kecakapan Khusus","C. 16 - 20 tahun","D. 11 - 15 tahun"]', 'A. Tunas Kelapa'),
(1, 'Pencipta lambang Tunas Kelapa adalah...', '["A. Ramu, Rakit, Terap","B. Soenardjo Atmodipuro","C. Masyarakat dan Organisasi","D. Satyaku Kudarmakan, Darmaku Kubaktikan"]', 'B. Soenardjo Atmodipuro'),
(1, 'Bentuk lambang Pramuka Internasional (WOSM) adalah...', '["A. Mula, Bantu, Tata","B. 7 - 10 tahun","C. Bunga Lily (Fleur-de-lis)","D. 16 - 20 tahun"]', 'C. Bunga Lily (Fleur-de-lis)'),
(1, 'Gerakan Pramuka resmi diperkenalkan kepada rakyat Indonesia pada tanggal...', '["A. 14 Agustus 1961","B. 14 Agustus 1960","C. 12 Agustus 1961","D. 14 September 1961"]', 'A. 14 Agustus 1961'),
(1, 'Oleh karena itu, Hari Pramuka di Indonesia diperingati setiap tanggal...', '["A. 14 Agustus","B. 9 Agustus","C. 12 Agustus","D. 19 Agustus"]', 'A. 14 Agustus'),
(1, 'Undang-Undang yang mengatur tentang Gerakan Pramuka saat ini adalah...', '["A. 11 - 15 tahun","B. UU No. 12 Tahun 2010","C. Lord Robert Baden Powell","D. Tanda Kecakapan Umum"]', 'B. UU No. 12 Tahun 2010'),
(1, 'Motto Gerakan Pramuka adalah...', '["A. Satyaku Kudarmakan, Darmaku Kubaktikan","B. 21 - 25 tahun","C. Trisatya dan Dasadarma","D. Bunga Lily (Fleur-de-lis)"]', 'A. Satyaku Kudarmakan, Darmaku Kubaktikan'),
(1, 'Tingkatan tertinggi dalam setiap golongan Pramuka yang telah memenuhi syarat pencapaian Garuda disebut...', '["A. Ambalan","B. Soenardjo Atmodipuro","C. Pramuka Garuda","D. Tanda Kecakapan Umum"]', 'C. Pramuka Garuda'),

-- ==========================================
-- BAB 3: Biografi Baden Powell
-- ==========================================
(3, 'Nama lengkap Bapak Pandu Dunia adalah...', '["A. Robert Stephenson Smyth Baden-Powell","B. Admiral William T. Smyth","C. 22 anak","D. Rudyard Kipling"]', 'A. Robert Stephenson Smyth Baden-Powell'),
(3, 'Baden-Powell lahir di kota...', '["A. Olympia Hall","B. Pembantu Letnan (Sub-Lieutenant)","C. London","D. 1899"]', 'C. London'),
(3, 'Tanggal lahir Baden-Powell adalah...', '["A. 22 Februari 1858","B. 22 Februari 1857","C. 22 Februari 1856","D. 24 Februari 1857"]', 'B. 22 Februari 1857'),
(3, 'Nama ayah Baden-Powell adalah...', '["A. Prof. Domine Baden-Powell","B. Mafeking","C. Impeesa","D. Robert Stephenson Smyth Baden-Powell"]', 'A. Prof. Domine Baden-Powell'),
(3, 'Profesi ayah Baden-Powell adalah seorang...', '["A. Kapak menancap di balok kayu","B. Guru Besar Geometri di Universitas Oxford","C. World Organization of the Scout Movement","D. Miss Henrietta Grace Smyth"]', 'B. Guru Besar Geometri di Universitas Oxford'),
(3, 'Nama ibu dari Baden-Powell adalah...', '["A. Letnan Jenderal","B. 13th Hussars","C. Miss Henrietta Grace Smyth","D. World Organization of the Scout Movement"]', 'C. Miss Henrietta Grace Smyth'),
(3, 'Ayah dari ibu Baden-Powell (kakek dari pihak ibu) adalah seorang laksamana bernama...', '["A. Admiral William T. Smyth","B. 1899 - 1900","C. The Jungle Book","D. 22 Februari 1857"]', 'A. Admiral William T. Smyth'),
(3, 'Ayah Baden-Powell meninggal dunia ketika Baden-Powell berusia...', '["A. 3 tahun","B. 8 tahun","C. 1 tahun","D. 7 tahun"]', 'A. 3 tahun'),
(3, 'Julukan Baden-Powell saat bersekolah di Charterhouse School karena kebiasaannya mandi air dingin adalah...', '["A. London","B. Bathing Towel","C. Dr. Haig Brown","D. Gilwell Park"]', 'B. Bathing Towel'),
(3, 'Kepala sekolah di Charterhouse yang sangat berpengaruh terhadap pembentukan karakter Baden-Powell adalah...', '["A. Dr. Haig Brown","B. Pembantu Letnan (Sub-Lieutenant)","C. Gilwell Park","D. 1919"]', 'A. Dr. Haig Brown'),
(3, 'Setelah lulus dari Charterhouse, Baden-Powell mengikuti ujian militer dan lulus kavaleri dengan urutan ke...', '["A. Impeesa","B. Dua","C. 22 Februari 1857","D. 1910"]', 'B. Dua'),
(3, 'Pasukan kavaleri yang pertama kali ditempati Baden-Powell di India adalah...', '["A. 1918","B. 1929","C. 13th Hussars","D. Prof. Domine Baden-Powell"]', 'C. 13th Hussars'),
(3, 'Baden-Powell pertama kali ditugaskan ke India sebagai prajurit muda pada tahun...', '["A. 1876","B. 1879","C. 1875","D. 1872"]', 'A. 1876'),
(3, 'Pangkat pertama Baden-Powell saat bergabung di ketentaraan di India adalah...', '["A. Saya telah pulang","B. 1910","C. Pembantu Letnan (Sub-Lieutenant)","D. 1899 - 1900"]', 'C. Pembantu Letnan (Sub-Lieutenant)'),
(3, 'Suku Zulu, Ashanti, dan Matabele di Afrika memberikan julukan khusus kepada Baden-Powell, yaitu...', '["A. Pembantu Letnan (Sub-Lieutenant)","B. Impeesa","C. 1908","D. 1876"]', 'B. Impeesa'),
(3, 'Arti dari julukan "Impeesa" yang diberikan oleh suku di Afrika adalah...', '["A. Miss Henrietta Grace Smyth","B. Saya telah pulang","C. Serigala yang tidak pernah tidur","D. Prof. Domine Baden-Powell"]', 'C. Serigala yang tidak pernah tidur'),
(3, 'Baden-Powell berhasil mempertahankan sebuah kota dari kepungan bangsa Boer di Afrika Selatan selama 217 hari. Kota tersebut bernama...', '["A. 1918","B. Bathing Towel","C. 1876","D. Mafeking"]', 'D. Mafeking'),
(3, 'Peristiwa pengepungan kota Mafeking terjadi pada tahun...', '["A. Gilwell Park","B. 1899 - 1900","C. Agnes Baden-Powell","D. 1910"]', 'B. 1899 - 1900'),
(3, 'Buku panduan pelacakan militer yang ditulis Baden-Powell dan kelak disukai oleh anak-anak muda Inggris adalah...', '["A. Dinizulu","B. Aids to Scouting","C. The Jungle Book","D. Serigala yang tidak pernah tidur"]', 'B. Aids to Scouting'),
(3, 'Buku "Aids to Scouting" diterbitkan pada tahun...', '["A. 1899","B. 1903","C. 1901","D. 1897"]', 'A. 1899'),
(3, 'Perkemahan percobaan kepanduan pertama kali diadakan oleh Baden-Powell di sebuah pulau bernama...', '["A. Dua","B. Pulau Brownsea","C. Agnes Baden-Powell","D. 3 tahun"]', 'B. Pulau Brownsea'),
(3, 'Perkemahan di Pulau Brownsea yang menjadi tonggak sejarah kepramukaan dilaksanakan pada tahun...', '["A. 1908","B. 1907","C. 1909","D. 1906"]', 'B. 1907'),
(3, 'Berapa jumlah anak laki-laki yang mengikuti perkemahan percobaan di Pulau Brownsea?', '["A. 20 anak","B. 27 anak","C. 22 anak","D. 23 anak"]', 'C. 22 anak'),
(3, 'Teman tentara yang membantu Baden-Powell mengurus perkemahan di Pulau Brownsea adalah...', '["A. Mayor Kenneth McLaren","B. Dinizulu","C. Saya telah pulang","D. 1920"]', 'A. Mayor Kenneth McLaren'),
(3, 'Buku panduan utama yang menjadi cikal bakal berdirinya gerakan kepanduan dunia adalah...', '["A. 1899 - 1900","B. Gilwell Park","C. Scouting for Boys","D. Impeesa"]', 'C. Scouting for Boys'),
(3, 'Buku "Scouting for Boys" karya Baden-Powell pertama kali diterbitkan pada tahun...', '["A. 1905","B. 1908","C. 1913","D. 1906"]', 'B. 1908'),
(3, 'Organisasi kepanduan putri (Girl Guides) pertama kali dibentuk dengan bantuan adik perempuan Baden-Powell yang bernama...', '["A. Nyeri","B. Bathing Towel","C. Agnes Baden-Powell","D. 83 tahun"]', 'C. Agnes Baden-Powell'),
(3, 'Organisasi Girl Guides (Kepanduan Putri) dirintis pada tahun...', '["A. 1915","B. 1910","C. 1905","D. 1911"]', 'B. 1910'),
(3, 'Kepanduan untuk golongan anak-anak (Siaga/Wolf Cub) didirikan oleh Baden-Powell pada tahun...', '["A. 1921","B. 1919","C. 1916","D. 1920"]', 'C. 1916'),
(3, 'Buku panduan yang digunakan Baden-Powell untuk menginspirasi golongan Siaga (Wolf Cub) adalah...', '["A. 1916","B. The Jungle Book","C. Letnan Jenderal","D. Admiral William T. Smyth"]', 'B. The Jungle Book'),
(3, 'Penulis buku "The Jungle Book" yang menginspirasi pembentukan golongan Siaga adalah...', '["A. Rudyard Kipling","B. 8 Januari 1941","C. Rovering to Success","D. 1916"]', 'A. Rudyard Kipling'),
(3, 'Kepanduan untuk golongan pemuda (Penegak/Rover Scout) dibentuk pada tahun...', '["A. 1922","B. 1918","C. 1917","D. 1919"]', 'B. 1918'),
(3, 'Buku panduan untuk Rover Scout yang ditulis oleh Baden-Powell pada tahun 1922 berjudul...', '["A. Olympia Hall","B. Robert Stephenson Smyth Baden-Powell","C. Rovering to Success","D. 1919"]', 'C. Rovering to Success'),
(3, 'Jambore Kepanduan Dunia pertama kali diadakan di gedung...', '["A. Olympia Hall","B. Mayor Kenneth McLaren","C. 83 tahun","D. 1908"]', 'A. Olympia Hall'),
(3, 'Jambore Dunia pertama diadakan di kota London pada tahun...', '["A. 1916","B. 1920","C. 1922","D. 1924"]', 'B. 1920'),
(3, 'Pada malam terakhir Jambore Dunia pertama, Baden-Powell secara resmi diangkat menjadi...', '["A. World Organization of the Scout Movement","B. Guru Besar Geometri di Universitas Oxford","C. Bapak Pandu Dunia (Chief Scout of the World)","D. 22 anak"]', 'C. Bapak Pandu Dunia (Chief Scout of the World)'),
(3, 'Gelar kehormatan "Lord" (Baron) dianugerahkan kepada Baden-Powell oleh Raja George V pada tahun...', '["A. 1932","B. 1926","C. 1929","D. 1928"]', 'C. 1929'),
(3, 'Nama istri Baden-Powell yang kelak menjadi Chief Guide of the World adalah...', '["A. Miss Henrietta Grace Smyth","B. Olave St. Clair Soames","C. Robert Stephenson Smyth Baden-Powell","D. Aids to Scouting"]', 'B. Olave St. Clair Soames'),
(3, 'Baden-Powell pensiun dari dinas kemiliteran Inggris dengan pangkat terakhir...', '["A. 1899 - 1900","B. Letnan Jenderal","C. Dua","D. Dinizulu"]', 'B. Letnan Jenderal'),
(3, 'Raja Inggris yang menyarankan Baden-Powell untuk pensiun dari militer agar bisa membesarkan Gerakan Kepanduan adalah...', '["A. Olave St. Clair Soames","B. Bathing Towel","C. Raja Edward VII","D. Letnan Jenderal"]', 'C. Raja Edward VII'),
(3, 'Pada tahun 1919, W. de Bois Maclaren menyumbangkan sebidang tanah untuk pusat pelatihan pembina pramuka yang diberi nama...', '["A. Dinizulu","B. Raja Edward VII","C. Gilwell Park","D. Agnes Baden-Powell"]', 'C. Gilwell Park'),
(3, 'Kursus Pembina Pramuka (Wood Badge) pertama kali diselenggarakan di Gilwell Park pada tahun...', '["A. 1923","B. 1919","C. 1917","D. 1920"]', 'B. 1919'),
(3, 'Kalung manik-manik kayu (Wood Badge) berasal dari kalung pimpinan suku Afrika yang pernah dikalahkan oleh Baden-Powell, bernama...', '["A. Gilwell Park","B. Dinizulu","C. Pulau Brownsea","D. 1907"]', 'B. Dinizulu'),
(3, 'Simbol dari pusat pelatihan pembina Gilwell Park adalah...', '["A. Prof. Domine Baden-Powell","B. Aids to Scouting","C. Kapak menancap di balok kayu","D. The Jungle Book"]', 'C. Kapak menancap di balok kayu'),
(3, 'Baden-Powell menghabiskan masa tuanya dan meninggal dunia di negara...', '["A. Rovering to Success","B. Mayor Kenneth McLaren","C. 1876","D. Kenya"]', 'D. Kenya'),
(3, 'Baden-Powell meninggal dunia pada tanggal...', '["A. 8 Januari 1941","B. 6 Januari 1941","C. 8 Januari 1942","D. 8 Agustus 1941"]', 'A. 8 Januari 1941'),
(3, 'Baden-Powell dimakamkan di pemakaman St. Peter, di kota...', '["A. 1907","B. 13th Hussars","C. Nyeri","D. 1899"]', 'C. Nyeri'),
(3, 'Usia Baden-Powell saat meninggal dunia adalah...', '["A. 81 tahun","B. 80 tahun","C. 83 tahun","D. 82 tahun"]', 'C. 83 tahun'),
(3, 'Pada batu nisan makam Baden-Powell terdapat tanda jejak kepanduan berupa lingkaran dengan titik di tengah yang memiliki arti...', '["A. Saya telah pulang","B. Mayor Kenneth McLaren","C. Dr. Haig Brown","D. Robert Stephenson Smyth Baden-Powell"]', 'A. Saya telah pulang'),
(3, 'Organisasi kepanduan dunia saat ini bernaung di bawah organisasi bernama WOSM, singkatan dari...', '["A. Olave St. Clair Soames","B. World Organization of the Scout Movement","C. Kapak menancap di balok kayu","D. Serigala yang tidak pernah tidur"]', 'B. World Organization of the Scout Movement'),

-- ==========================================
-- BAB 5: Scouting for Boys
-- ==========================================
(5, 'Bab 5 dalam buku referensi Boyman secara khusus membahas rangkuman dari buku legendaris karya Baden-Powell yang berjudul...', '["A. Simpul Mati (Reef Knot)","B. Scouting for Boys","C. Mafeking Cadet Corps","D. Survival (Bertahan Hidup)"]', 'B. Scouting for Boys'),
(5, 'Buku Scouting for Boys pada dasarnya dibagi ke dalam beberapa sub-bab yang disebut dengan istilah...', '["A. Perkemahan (Camping)","B. Binatang dan Tumbuh-tumbuhan","C. Cerita Api Unggun","D. Simpul Tiang (Bowline)"]', 'C. Cerita Api Unggun'),
(5, 'Ada berapa total Cerita Api Unggun (Campfire Yarns) yang menjadi susunan utama materi Scouting for Boys?', '["A. 21 Cerita","B. 29 Cerita","C. 23 Cerita","D. 26 Cerita"]', 'D. 26 Cerita'),
(5, 'Cerita Api Unggun ke-1 membahas sejarah tentang pasukan anak laki-laki di Afrika yang menjadi inspirasi kepanduan, yang disebut...', '["A. Mafeking Cadet Corps","B. Sistem Regu (Patrol System)","C. Perkemahan (Camping)","D. Survival (Bertahan Hidup)"]', 'A. Mafeking Cadet Corps'),
(5, 'Pemimpin pasukan anak-anak pada masa pengepungan Mafeking tersebut adalah...', '["A. Pionering / Kepeloporan","B. Lord Edward Cecil","C. Simpul Mati (Reef Knot)","D. Simpul Anyam (Sheet Bend)"]', 'B. Lord Edward Cecil'),
(5, 'Baden-Powell menyadari kehebatan pasukan anak-anak di Mafeking yang kemudian menjadi cikal bakal pentingnya peran kaum muda. Pengepungan kota Mafeking terjadi di negara...', '["A. Afrika Selatan","B. Simpul Mati (Reef Knot)","C. Simpul Pangkal (Clove Hitch)","D. Good Turn (Berbuat Kebaikan)"]', 'A. Afrika Selatan'),
(5, 'Cerita Api Unggun ke-4 membahas inti dari sistem kepramukaan yang membagi anggota ke dalam kelompok kecil, disebut dengan...', '["A. Masakan di Perkemahan (Camp Cooking)","B. Good Turn (Berbuat Kebaikan)","C. Sistem Regu (Patrol System)","D. Raja Arthur"]', 'C. Sistem Regu (Patrol System)'),
(5, 'Menurut gagasan awal Baden-Powell, jumlah anggota yang ideal dalam satu regu pramuka (patrol) adalah...', '["A. Perkemahan (Camping)","B. 6 sampai 8 orang","C. Santo George (St. George)","D. Binatang dan Tumbuh-tumbuhan"]', 'B. 6 sampai 8 orang'),
(5, 'Sebutan untuk pemimpin regu dalam bahasa Inggris yang dicetuskan oleh Baden-Powell adalah...', '["A. Raja Arthur","B. Cerita Api Unggun","C. Ikatan Palang (Square Lashing)","D. Patrol Leader"]', 'D. Patrol Leader'),
(5, 'Cerita Api Unggun ke-8 membahas tentang keterampilan membuat bangunan darurat menggunakan kayu dan tali, yang dalam istilah kepramukaan disebut...', '["A. Pionering / Kepeloporan","B. Masakan di Perkemahan (Camp Cooking)","C. Jalan ke arah kanan","D. Be Prepared (Selalu Siap)"]', 'A. Pionering / Kepeloporan'),
(5, 'Simpul dasar dalam pionering yang berguna untuk menyambung dua utas tali yang sama besar dan tidak licin adalah...', '["A. Simpul Mati (Reef Knot)","B. Ikatan Palang (Square Lashing)","C. Diare dan Disentri","D. Kesehatan fisik dan kebugaran tubuh"]', 'A. Simpul Mati (Reef Knot)'),
(5, 'Simpul yang berguna untuk mengikat leher binatang agar tidak tercekik, serta sering menjadi simpul dasar penyelamatan adalah...', '["A. Simpul Mati (Reef Knot)","B. Survival (Bertahan Hidup)","C. Simpul Tiang (Bowline)","D. Perkemahan (Camping)"]', 'C. Simpul Tiang (Bowline)'),
(5, 'Simpul yang paling sering digunakan untuk memulai dan mengakhiri sebuah ikatan pada tongkat pionering adalah...', '["A. Pionering / Kepeloporan","B. Simpul Pangkal (Clove Hitch)","C. Perkemahan (Camping)","D. 23 April"]', 'B. Simpul Pangkal (Clove Hitch)'),
(5, 'Simpul yang digunakan untuk menyambung dua utas tali yang ukurannya tidak sama besar dan dalam keadaan kering adalah...', '["A. Good Turn (Berbuat Kebaikan)","B. Tetap tenang dan tidak panik","C. Simpul Mati (Reef Knot)","D. Simpul Anyam (Sheet Bend)"]', 'D. Simpul Anyam (Sheet Bend)'),
(5, 'Ikatan yang digunakan untuk menggabungkan dua buah tongkat yang bersilangan tegak lurus (membentuk sudut 90 derajat) adalah...', '["A. Ikatan Palang (Square Lashing)","B. Kewarganegaraan (Citizenship)","C. Sistem Regu (Patrol System)","D. Diare dan Disentri"]', 'A. Ikatan Palang (Square Lashing)'),
(5, 'Cerita Api Unggun ke-9 membahas mengenai kehidupan di alam terbuka, yaitu rutinitas...', '["A. Kewarganegaraan (Citizenship)","B. Perkemahan (Camping)","C. Binatang dan Tumbuh-tumbuhan","D. Santo George (St. George)"]', 'B. Perkemahan (Camping)'),
(5, 'Hal yang paling utama dan penting untuk diperhatikan saat memilih lokasi untuk mendirikan tenda perkemahan adalah...', '["A. Kesatria Meja Bundar (Knights of the Round Table)","B. Saya telah pulang / Kembali ke perkemahan","C. Dekat sumber air bersih dan aman dari bahaya alam","D. Melakukan tekanan langsung pada area luka / balut tekan"]', 'C. Dekat sumber air bersih dan aman dari bahaya alam'),
(5, 'Cerita Api Unggun ke-10 memberikan panduan teknis yang sangat dibutuhkan regu mandiri, yaitu tentang...', '["A. Masakan di Perkemahan (Camp Cooking)","B. Binatang dan Tumbuh-tumbuhan","C. Simpul Anyam (Sheet Bend)","D. 6 sampai 8 orang"]', 'A. Masakan di Perkemahan (Camp Cooking)'),
(5, 'Salah satu makanan khas perkemahan ala Baden-Powell, di mana adonan tepung dililitkan pada sebatang kayu lalu dipanggang di atas bara api, disebut...', '["A. Mencari dan Mengikuti Jejak (Tracking)","B. Roti Lilit (Twist)","C. Perkemahan (Camping)","D. Patrol Leader"]', 'B. Roti Lilit (Twist)'),
(5, 'Cerita Api Unggun ke-11 dan 12 mengajarkan keterampilan mengasah kepekaan mata di alam terbuka, berupa...', '["A. 6 Latihan Fisik BP (BP Exercises)","B. Jalan ke arah kanan","C. Mencari dan Mengikuti Jejak (Tracking)","D. Survival (Bertahan Hidup)"]', 'C. Mencari dan Mengikuti Jejak (Tracking)'),
(5, 'Saat sedang mengikuti jejak di alam bebas, seorang Pramuka dianjurkan untuk berjalan dengan cara...', '["A. Menyelamatkan Hidup dan Penanganan Kecelakaan (P3K)","B. Mencari dan Mengikuti Jejak (Tracking)","C. Kesehatan fisik dan kebugaran tubuh","D. Tenang sambil memperhatikan keadaan tanah dan sekelilingnya"]', 'D. Tenang sambil memperhatikan keadaan tanah dan sekelilingnya'),
(5, 'Dalam sandi jejak Pramuka, susunan batu yang ditumpuk menjadi tiga bagian dan ditambahkan satu batu kecil di sebelah kanan memiliki arti...', '["A. Jalan ke arah kanan","B. Survival (Bertahan Hidup)","C. Roti Lilit (Twist)","D. Lord Edward Cecil"]', 'A. Jalan ke arah kanan'),
(5, 'Sebuah lingkaran yang digambar di tanah dengan titik di tengahnya merupakan tanda jejak kepanduan yang berarti...', '["A. Dekat sumber air bersih dan aman dari bahaya alam","B. Masakan di Perkemahan (Camp Cooking)","C. Saya telah pulang / Kembali ke perkemahan","D. Tetap tenang dan tidak panik"]', 'C. Saya telah pulang / Kembali ke perkemahan'),
(5, 'Cerita Api Unggun ke-13 menuntut seorang pandu untuk memiliki kemampuan observasi dan deduksi. Tokoh detektif fiksi yang sering dijadikan contoh oleh Baden-Powell untuk hal ini adalah...', '["A. 6 sampai 8 orang","B. Sherlock Holmes","C. Simpul Pangkal (Clove Hitch)","D. Scouting for Boys"]', 'B. Sherlock Holmes'),
(5, 'Cerita Api Unggun ke-14 berjudul "Menyembunyikan Diri - Mengendap" (Stalking). Mengendap sangat berguna di alam bebas untuk...', '["A. Mendekati dan mengamati hewan liar tanpa disadari oleh hewan tersebut","B. Melakukan tekanan langsung pada area luka / balut tekan","C. Terus mengasah keahlian dan akhlaknya secara mandiri agar hidupnya lebih berguna","D. Dekat sumber air bersih dan aman dari bahaya alam"]', 'A. Mendekati dan mengamati hewan liar tanpa disadari oleh hewan tersebut'),
(5, 'Aturan utama yang harus diperhatikan seorang Pramuka saat sedang mengendap mendekati target di alam liar adalah...', '["A. Tenang sambil memperhatikan keadaan tanah dan sekelilingnya","B. Menolong orang lain di setiap kesempatan","C. Bergerak berlawanan arah dengan hembusan angin","D. Good Turn (Berbuat Kebaikan)"]', 'C. Bergerak berlawanan arah dengan hembusan angin'),
(5, 'Cerita Api Unggun ke-15 dan 16 membahas apresiasi terhadap lingkungan hidup, yakni tentang pengetahuan...', '["A. Good Turn (Berbuat Kebaikan)","B. Binatang dan Tumbuh-tumbuhan","C. Sherlock Holmes","D. Masakan di Perkemahan (Camp Cooking)"]', 'B. Binatang dan Tumbuh-tumbuhan'),
(5, 'Prinsip konservasi dalam kepanduan menyatakan bahwa seorang Pramuka dilarang keras membunuh binatang apa pun, KECUALI...', '["A. Menyelamatkan Hidup dan Penanganan Kecelakaan (P3K)","B. Kesatria Meja Bundar (Knights of the Round Table)","C. Menyuruhnya berguling-guling di tanah atau membungkusnya rapat dengan selimut tebal","D. Ketika terancam bahaya atau terpaksa untuk bertahan hidup/makan"]', 'D. Ketika terancam bahaya atau terpaksa untuk bertahan hidup/makan'),
(5, 'Pengetahuan seorang Pramuka dalam mengenali berbagai jenis pohon liar, dedaunan, dan akar yang bisa dimakan sangat menunjang kemampuannya dalam bidang...', '["A. Survival (Bertahan Hidup)","B. Perkemahan (Camping)","C. Disiplin","D. 23 April"]', 'A. Survival (Bertahan Hidup)'),
(5, 'Cerita Api Unggun ke-17 berjudul "Bagaimana Supaya Kuat", yang memberikan instruksi agar kaum muda terbiasa menjaga...', '["A. Diare dan Disentri","B. Mafeking Cadet Corps","C. Kesehatan fisik dan kebugaran tubuh","D. Menolong orang lain di setiap kesempatan"]', 'C. Kesehatan fisik dan kebugaran tubuh'),
(5, 'Untuk melatih kebugaran tubuh setiap hari, Baden-Powell menyarankan rutinitas senam pagi yang dikenal sebagai...', '["A. Ketika terancam bahaya atau terpaksa untuk bertahan hidup/makan","B. 6 Latihan Fisik BP (BP Exercises)","C. Tetap tenang dan tidak panik","D. 6 sampai 8 orang"]', 'B. 6 Latihan Fisik BP (BP Exercises)'),
(5, 'Cerita Api Unggun ke-18 dan 19 mengulas tentang kebiasaan yang menyehatkan serta pencegahan penyakit. Baden-Powell sangat mewajibkan pandu bernapas dengan benar melalui...', '["A. Hidung, bukan mulut","B. Kewarganegaraan (Citizenship)","C. Simpul Pangkal (Clove Hitch)","D. Simpul Tiang (Bowline)"]', 'A. Hidung, bukan mulut'),
(5, 'Penyakit yang sering menyerang anggota perkemahan akibat meminum air mentah atau lingkungan perkemahan yang kurang bersih (sanitasi buruk) adalah...', '["A. Jalan ke arah kanan","B. Masakan di Perkemahan (Camp Cooking)","C. Scouting for Boys","D. Diare dan Disentri"]', 'D. Diare dan Disentri'),
(5, 'Cerita Api Unggun ke-20 bertemakan "Sikap Kesatria" (Chivalry). Inspirasi utama Baden-Powell dalam membentuk karakter Pramuka ini berasal dari legenda pahlawan kuno, yaitu...', '["A. Pria yang bertanggung jawab, mandiri, dan berkarakter mulia","B. Kesatria Meja Bundar (Knights of the Round Table)","C. Saya telah pulang / Kembali ke perkemahan","D. Menyuruhnya berguling-guling di tanah atau membungkusnya rapat dengan selimut tebal"]', 'B. Kesatria Meja Bundar (Knights of the Round Table)'),
(5, 'Raja legendaris Inggris yang memimpin para kesatria mulia dalam perumpamaan Baden-Powell tersebut adalah...', '["A. Good Turn (Berbuat Kebaikan)","B. Lord Edward Cecil","C. Raja Arthur","D. Sherlock Holmes"]', 'C. Raja Arthur'),
(5, 'Tokoh orang suci pelindung Inggris (Patron Saint) yang juga dijadikan sebagai pelindung simbolis kaum pandu di seluruh dunia karena keberaniannya membunuh naga adalah...', '["A. Santo George (St. George)","B. Bergerak berlawanan arah dengan hembusan angin","C. Ikatan Palang (Square Lashing)","D. Sherlock Holmes"]', 'A. Santo George (St. George)'),
(5, 'Hari peringatan St. George, yang sering dirayakan secara internasional oleh anggota Pramuka sebagai ajang pembaruan Janji Pramuka, jatuh pada tanggal...', '["A. 27 April","B. 23 April","C. 28 April","D. 22 April"]', 'B. 23 April'),
(5, 'Cerita Api Unggun ke-21 menekankan pada konsep utama watak yang membuat seorang pandu dihormati, yaitu...', '["A. Sherlock Holmes","B. Mafeking Cadet Corps","C. Disiplin","D. Kewarganegaraan (Citizenship)"]', 'C. Disiplin'),
(5, 'Ciri sejati dari kedisiplinan seorang Pramuka saat menerima instruksi dari pimpinannya adalah...', '["A. Mematuhi perintah dan aturan dengan sigap tanpa mengeluh","B. Pria yang bertanggung jawab, mandiri, dan berkarakter mulia","C. Kesatria Meja Bundar (Knights of the Round Table)","D. Ketika terancam bahaya atau terpaksa untuk bertahan hidup/makan"]', 'A. Mematuhi perintah dan aturan dengan sigap tanpa mengeluh'),
(5, 'Cerita Api Unggun ke-22 berjudul "Memperbaiki Diri". Hal ini mengajarkan filosofi bahwa seorang pandu sejati harus...', '["A. Mendekati dan mengamati hewan liar tanpa disadari oleh hewan tersebut","B. Dekat sumber air bersih dan aman dari bahaya alam","C. Menyuruhnya berguling-guling di tanah atau membungkusnya rapat dengan selimut tebal","D. Terus mengasah keahlian dan akhlaknya secara mandiri agar hidupnya lebih berguna"]', 'D. Terus mengasah keahlian dan akhlaknya secara mandiri agar hidupnya lebih berguna'),
(5, 'Cerita Api Unggun ke-23 dan 24 membahas tentang keterampilan vital yang harus dimiliki setiap Pramuka jika terjadi insiden darurat, yakni tentang...', '["A. Simpul Mati (Reef Knot)","B. Menyelamatkan Hidup dan Penanganan Kecelakaan (P3K)","C. Simpul Pangkal (Clove Hitch)","D. Jalan ke arah kanan"]', 'B. Menyelamatkan Hidup dan Penanganan Kecelakaan (P3K)'),
(5, 'Kaidah terpenting dan pertama kali yang harus dikuasai secara mental saat seorang Pramuka menghadapi situasi kecelakaan parah adalah...', '["A. Tetap tenang dan tidak panik","B. Sistem Regu (Patrol System)","C. Lord Edward Cecil","D. Menolong orang lain di setiap kesempatan"]', 'A. Tetap tenang dan tidak panik'),
(5, 'Apabila menemui korban yang mengalami pendarahan hebat (luka terbuka memancar), tindakan Pertolongan Pertama yang paling efektif dilakukan adalah...', '["A. Dekat sumber air bersih dan aman dari bahaya alam","B. Terus mengasah keahlian dan akhlaknya secara mandiri agar hidupnya lebih berguna","C. Melakukan tekanan langsung pada area luka / balut tekan","D. Warga negara yang aktif dan bermanfaat bagi negaranya"]', 'C. Melakukan tekanan langsung pada area luka / balut tekan'),
(5, 'Jika pakaian yang dikenakan oleh seseorang tiba-tiba tersambar api dan terbakar, tindakan penyelematan yang paling tepat diinstruksikan oleh Pramuka adalah...', '["A. Warga negara yang aktif dan bermanfaat bagi negaranya","B. Menyuruhnya berguling-guling di tanah atau membungkusnya rapat dengan selimut tebal","C. Mendekati dan mengamati hewan liar tanpa disadari oleh hewan tersebut","D. Pria yang bertanggung jawab, mandiri, dan berkarakter mulia"]', 'B. Menyuruhnya berguling-guling di tanah atau membungkusnya rapat dengan selimut tebal'),
(5, 'Cerita Api Unggun ke-25 mengingatkan tentang tujuan mulia kehadiran gerakan Pramuka dalam masyarakat, yaitu kewajiban untuk...', '["A. Jalan ke arah kanan","B. Santo George (St. George)","C. Kesatria Meja Bundar (Knights of the Round Table)","D. Menolong orang lain di setiap kesempatan"]', 'D. Menolong orang lain di setiap kesempatan'),
(5, 'Sebuah tradisi pandu yang diajarkan oleh Baden-Powell untuk melakukan setidaknya satu kebaikan kecil setiap harinya tanpa mengharap imbalan disebut dengan istilah...', '["A. Good Turn (Berbuat Kebaikan)","B. Jalan ke arah kanan","C. Santo George (St. George)","D. Raja Arthur"]', 'A. Good Turn (Berbuat Kebaikan)'),
(5, 'Cerita Api Unggun ke-26, yang menjadi bab pamungkas dalam materi buku Scouting for Boys, secara umum membahas tentang sikap tanggung jawab bermasyarakat, yakni...', '["A. Hidung, bukan mulut","B. Kewarganegaraan (Citizenship)","C. Pionering / Kepeloporan","D. Diare dan Disentri"]', 'B. Kewarganegaraan (Citizenship)'),
(5, 'Inti dari jiwa kewarganegaraan seorang Pramuka adalah kemauannya untuk memahami sejarah, pemerintahan, dan hukum bangsanya, agar kelak ia menjadi...', '["A. Mematuhi perintah dan aturan dengan sigap tanpa mengeluh","B. Saya telah pulang / Kembali ke perkemahan","C. Warga negara yang aktif dan bermanfaat bagi negaranya","D. Kesatria Meja Bundar (Knights of the Round Table)"]', 'C. Warga negara yang aktif dan bermanfaat bagi negaranya'),
(5, 'Semboyan kepanduan utama yang diperkenalkan Baden-Powell dalam buku ini, yang wajib dipraktikkan baik dalam kesiapan fisik maupun mental oleh pandu di seluruh dunia adalah...', '["A. Be Prepared (Selalu Siap)","B. 6 sampai 8 orang","C. Sherlock Holmes","D. Jalan ke arah kanan"]', 'A. Be Prepared (Selalu Siap)'),
(5, 'Pesan moral secara keseluruhan dari Scouting for Boys yang tercantum di Bab 5 Boyman adalah membentuk remaja agar tidak hanya menjadi sosok petualang alam bebas, tetapi juga menjadi...', '["A. Warga negara yang aktif dan bermanfaat bagi negaranya","B. Melakukan tekanan langsung pada area luka / balut tekan","C. Menolong orang lain di setiap kesempatan","D. Pria yang bertanggung jawab, mandiri, dan berkarakter mulia"]', 'D. Pria yang bertanggung jawab, mandiri, dan berkarakter mulia'),

-- ==========================================
-- BAB 9: Berkemah / Alam Bebas
-- ==========================================
(9, 'Pengertian berkemah dalam kepramukaan pada dasarnya adalah...', '["A. Pakaian ganti, sleeping bag, alat mandi, dan obat pribadi","B. Kegiatan hidup di alam bebas dengan menggunakan tenda sebagai tempat berlindung","C. Disaring dengan kain lalu direbus hingga mendidih (matang) untuk membunuh bakteri","D. Menghentikan aktivitas berisik dan beristirahat agar tidak mengganggu makhluk hidup dan tenda lain"]', 'B. Kegiatan hidup di alam bebas dengan menggunakan tenda sebagai tempat berlindung'),
(9, 'Salah satu sasaran dan motivasi utama dari kegiatan berkemah bagi anggota Pramuka adalah...', '["A. Melatih kemandirian, gotong royong, dan kedisiplinan di alam terbuka","B. Mencegah air hujan masuk/menggenangi bagian dalam tenda","C. Mengeluarkan dan membersihkan seluruh barang dari dalam tenda","D. 15-20 meter dari sumber air agar tidak mencemari mata air"]', 'A. Melatih kemandirian, gotong royong, dan kedisiplinan di alam terbuka'),
(9, 'Tahap pertama yang mutlak harus dilakukan sebelum menyelenggarakan kegiatan perkemahan adalah...', '["A. Melatih kemandirian, gotong royong, dan kedisiplinan di alam terbuka","B. Menyusun Perencanaan dan Persiapan (surat izin, lokasi, anggaran)","C. Praktis, awet/tahan lama, bernilai gizi tinggi, dan mudah dimasak","D. Obat penyakit khusus/alergi yang diidap oleh diri sendiri"]', 'B. Menyusun Perencanaan dan Persiapan (surat izin, lokasi, anggaran)'),
(9, 'Syarat utama tapak kemah (lokasi perkemahan) yang baik dan aman adalah...', '["A. Disaring dengan kain lalu direbus hingga mendidih (matang) untuk membunuh bakteri","B. Dekat dengan sumber air yang bersih dan aman dari bahaya alam","C. Miring 45-60 derajat berlawanan dengan arah tarikan tali tenda","D. Membuat alas perapian (dari tanah/batu) atau tidak merusak area vegetasi di bawahnya"]', 'B. Dekat dengan sumber air yang bersih dan aman dari bahaya alam'),
(9, 'Mengapa mendirikan tenda di dasar cekungan (lembah sempit) sangat dilarang dalam aturan perkemahan?', '["A. Melatih kemandirian, gotong royong, dan kedisiplinan di alam terbuka","B. Dekat dengan sumber air yang bersih dan aman dari bahaya alam","C. Sangat berbahaya jika terjadi hujan lebat karena rawan banjir bandang/genangan air","D. Dikumpulkan dalam kantong sampah lalu dibawa turun/pulang (Pack it in, Pack it out)"]', 'C. Sangat berbahaya jika terjadi hujan lebat karena rawan banjir bandang/genangan air'),
(9, 'Mendirikan tenda di bawah pohon tua yang sudah lapuk sangat dihindari karena...', '["A. Mengeluarkan dan membersihkan seluruh barang dari dalam tenda","B. Rawan tertimpa dahan atau pohon tumbang jika ada angin kencang","C. Tenda harus dalam keadaan benar-benar kering agar tidak berjamur","D. Sangat berbahaya jika terjadi hujan lebat karena rawan banjir bandang/genangan air"]', 'B. Rawan tertimpa dahan atau pohon tumbang jika ada angin kencang'),
(9, 'Arah pintu tenda yang ideal saat didirikan di alam bebas sebaiknya...', '["A. Menyusun Perencanaan dan Persiapan (surat izin, lokasi, anggaran)","B. Membelakangi atau menyamping dari arah hembusan angin utama","C. 15-20 meter dari sumber air agar tidak mencemari mata air","D. Mencegah air hujan masuk/menggenangi bagian dalam tenda"]', 'B. Membelakangi atau menyamping dari arah hembusan angin utama'),
(9, 'Tujuan utama membuat parit kecil di sekeliling tenda saat berkemah adalah...', '["A. Simpul Tali Tenda (Taut-line Hitch)","B. Tenda, alat masak regu (nesting), dan kotak P3K regu","C. Mencegah air hujan masuk/menggenangi bagian dalam tenda","D. Menyalakan api, kompor, lentera minyak, atau lilin"]', 'C. Mencegah air hujan masuk/menggenangi bagian dalam tenda'),
(9, 'Tenda darurat sementara yang dibuat dari bahan alam atau jas hujan (ponco) dinamakan...', '["A. Bivak","B. Nesting","C. Flysheet","D. Ponco"]', 'A. Bivak'),
(9, 'Tenda standar beregu yang sering digunakan oleh Pramuka Penggalang, bentuknya seperti rumah dengan atap segitiga disebut...', '["A. Groundsheet / Terpal","B. Survival Kit","C. Tenda Prisma (Tenda Regu)","D. Ransel (Carrier / Backpack)"]', 'C. Tenda Prisma (Tenda Regu)'),
(9, 'Agar patok (pasak) tenda menancap kuat menahan tarikan tali, kemiringan pasak yang ditancapkan ke tanah sebaiknya bersudut...', '["A. 15-20 meter dari sumber air agar tidak mencemari mata air","B. Miring 45-60 derajat berlawanan dengan arah tarikan tali tenda","C. Sangat berbahaya jika terjadi hujan lebat karena rawan banjir bandang/genangan air","D. Perlengkapan Pribadi (Perorangan) dan Perlengkapan Regu (Kelompok)"]', 'B. Miring 45-60 derajat berlawanan dengan arah tarikan tali tenda'),
(9, 'Simpul yang paling tepat digunakan untuk mengikatkan tali tenda pada pasak agar mudah dikencangkan dan dikendurkan adalah...', '["A. Menyalakan api, kompor, lentera minyak, atau lilin","B. Sleeping Bag (Kantong Tidur)","C. Ransel (Carrier / Backpack)","D. Simpul Tali Tenda (Taut-line Hitch)"]', 'D. Simpul Tali Tenda (Taut-line Hitch)'),
(9, 'Perlengkapan perkemahan dibagi menjadi dua macam, yaitu...', '["A. Perlengkapan Pribadi (Perorangan) dan Perlengkapan Regu (Kelompok)","B. STOP (Stop, Think, Observe, Plan) dan tidak panik","C. Pakaian ganti, sleeping bag, alat mandi, dan obat pribadi","D. Mengeluarkan dan membersihkan seluruh barang dari dalam tenda"]', 'A. Perlengkapan Pribadi (Perorangan) dan Perlengkapan Regu (Kelompok)'),
(9, 'Berikut ini yang termasuk ke dalam Perlengkapan Pribadi saat berkemah adalah...', '["A. Melatih kemandirian, gotong royong, dan kedisiplinan di alam terbuka","B. Pakaian ganti, sleeping bag, alat mandi, dan obat pribadi","C. Obat penyakit khusus/alergi yang diidap oleh diri sendiri","D. 15-20 meter dari sumber air agar tidak mencemari mata air"]', 'B. Pakaian ganti, sleeping bag, alat mandi, dan obat pribadi'),
(9, 'Berikut ini yang termasuk ke dalam Perlengkapan Regu adalah...', '["A. Mengeluarkan dan membersihkan seluruh barang dari dalam tenda","B. Rawan tertimpa dahan atau pohon tumbang jika ada angin kencang","C. Tenda, alat masak regu (nesting), dan kotak P3K regu","D. STOP (Stop, Think, Observe, Plan) dan tidak panik"]', 'C. Tenda, alat masak regu (nesting), dan kotak P3K regu'),
(9, 'Alat pelindung tubuh dari suhu dingin saat tidur di dalam tenda yang bentuknya seperti kepompong disebut...', '["A. Simpul Tali Tenda (Taut-line Hitch)","B. Sleeping Bag (Kantong Tidur)","C. Tenda Prisma (Tenda Regu)","D. Survival Kit"]', 'B. Sleeping Bag (Kantong Tidur)'),
(9, 'Alat berupa alas tidur berbahan busa/spons yang berfungsi menahan hawa dingin dari tanah agar tidak langsung mengenai tubuh disebut...', '["A. Groundsheet / Terpal","B. Matras","C. Hipotermia","D. Flysheet"]', 'B. Matras'),
(9, 'Tas besar khusus untuk membawa perlengkapan berkemah yang bentuknya dirancang mengikuti anatomi punggung disebut...', '["A. Survival Kit","B. Groundsheet / Terpal","C. Ransel (Carrier / Backpack)","D. Sleeping Bag (Kantong Tidur)"]', 'C. Ransel (Carrier / Backpack)'),
(9, 'Prinsip dasar saat melakukan "Packing" (mengepak barang ke dalam ransel) agar tidak membuat punggung cepat lelah adalah...', '["A. Dikumpulkan dalam kantong sampah lalu dibawa turun/pulang (Pack it in, Pack it out)","B. Barang berat ditaruh di atas, barang ringan di bawah dan menempel punggung","C. Disaring dengan kain lalu direbus hingga mendidih (matang) untuk membunuh bakteri","D. Menahan dingin, melindungi dari duri, goresan ranting, dan gigitan serangga"]', 'B. Barang berat ditaruh di atas, barang ringan di bawah dan menempel punggung'),
(9, 'Selain masalah berat, prinsip "Packing" yang baik untuk melindungi barang dari hujan adalah...', '["A. Barang berat ditaruh di atas, barang ringan di bawah dan menempel punggung","B. Melapisi bagian dalam ransel dengan kantong plastik sampah (Trash Bag) besar sebelum diisi barang","C. Berat, tidak menyerap keringat, susah bergerak, dan sangat lama kering jika basah (bisa memicu hipotermia)","D. Menghentikan aktivitas berisik dan beristirahat agar tidak mengganggu makhluk hidup dan tenda lain"]', 'B. Melapisi bagian dalam ransel dengan kantong plastik sampah (Trash Bag) besar sebelum diisi barang'),
(9, 'Jas hujan berukuran besar berbentuk kelelawar yang dapat dialihfungsikan sebagai atap bivak darurat dinamakan...', '["A. Matras","B. Survival Kit","C. Ponco","D. Bivak"]', 'C. Ponco'),
(9, 'Syarat bahan makanan yang ideal untuk dibawa saat perkemahan adalah...', '["A. Obat penyakit khusus/alergi yang diidap oleh diri sendiri","B. Praktis, awet/tahan lama, bernilai gizi tinggi, dan mudah dimasak","C. Melatih kemandirian, gotong royong, dan kedisiplinan di alam terbuka","D. 15-20 meter dari sumber air agar tidak mencemari mata air"]', 'B. Praktis, awet/tahan lama, bernilai gizi tinggi, dan mudah dimasak'),
(9, 'Alat masak portabel berbahan aluminium yang sering digunakan oleh militer dan pramuka karena bisa disusun menjadi satu wadah ringkas disebut...', '["A. Flysheet","B. Hipotermia","C. Nesting","D. Matras"]', 'C. Nesting'),
(9, 'Lokasi yang TEPAT untuk menyalakan perapian atau kompor saat berkemah adalah...', '["A. Berat, tidak menyerap keringat, susah bergerak, dan sangat lama kering jika basah (bisa memicu hipotermia)","B. Dikumpulkan dalam kantong sampah lalu dibawa turun/pulang (Pack it in, Pack it out)","C. Di luar tenda pada tempat terbuka dan aman dari tiupan angin kencang atau dedaunan kering","D. Melapisi bagian dalam ransel dengan kantong plastik sampah (Trash Bag) besar sebelum diisi barang"]', 'C. Di luar tenda pada tempat terbuka dan aman dari tiupan angin kencang atau dedaunan kering'),
(9, 'Hal yang mutlak DILARANG dilakukan di dalam tenda karena sangat berbahaya adalah...', '["A. Menyalakan api, kompor, lentera minyak, atau lilin","B. Simpul Tali Tenda (Taut-line Hitch)","C. Pakaian ganti, sleeping bag, alat mandi, dan obat pribadi","D. Perlengkapan Pribadi (Perorangan) dan Perlengkapan Regu (Kelompok)"]', 'A. Menyalakan api, kompor, lentera minyak, atau lilin'),
(9, 'Pembuatan fasilitas MCK (Mandi Cuci Kakus) darurat di area kemah harus berjarak minimal...', '["A. Berjaga secara bergantian dan tidak jauh dari api/sumber cahaya darurat","B. Rawan tertimpa dahan atau pohon tumbang jika ada angin kencang","C. 15-20 meter dari sumber air agar tidak mencemari mata air","D. Pakaian berbahan katun/ripstop yang menyerap keringat, kuat, dan cepat kering (PDL)"]', 'C. 15-20 meter dari sumber air agar tidak mencemari mata air'),
(9, 'Manajemen sampah di area perkemahan untuk jenis sampah anorganik (plastik, kaleng, kaca) yang paling benar adalah...', '["A. Melakukan evaluasi kegiatan, membersihkan dan merawat kembali peralatan agar siap dipakai di kemudian hari","B. Berat, tidak menyerap keringat, susah bergerak, dan sangat lama kering jika basah (bisa memicu hipotermia)","C. Melapisi bagian dalam ransel dengan kantong plastik sampah (Trash Bag) besar sebelum diisi barang","D. Dikumpulkan dalam kantong sampah lalu dibawa turun/pulang (Pack it in, Pack it out)"]', 'D. Dikumpulkan dalam kantong sampah lalu dibawa turun/pulang (Pack it in, Pack it out)'),
(9, 'Sampah organik (sisa makanan) di area perkemahan sebaiknya...', '["A. Menghentikan aktivitas berisik dan beristirahat agar tidak mengganggu makhluk hidup dan tenda lain","B. Dikubur dalam lubang kecil yang tertutup rapat agak jauh dari tenda agar tidak mengundang hewan","C. Melapisi bagian dalam ransel dengan kantong plastik sampah (Trash Bag) besar sebelum diisi barang","D. Di luar tenda pada tempat terbuka dan aman dari tiupan angin kencang atau dedaunan kering"]', 'B. Dikubur dalam lubang kecil yang tertutup rapat agak jauh dari tenda agar tidak mengundang hewan'),
(9, 'Saat mengambil air minum dari sungai atau mata air alam, langkah wajib yang harus dilakukan sebelum meminumnya adalah...', '["A. Praktis, awet/tahan lama, bernilai gizi tinggi, dan mudah dimasak","B. Disaring dengan kain lalu direbus hingga mendidih (matang) untuk membunuh bakteri","C. Membuat alas perapian (dari tanah/batu) atau tidak merusak area vegetasi di bawahnya","D. Pakaian ganti, sleeping bag, alat mandi, dan obat pribadi"]', 'B. Disaring dengan kain lalu direbus hingga mendidih (matang) untuk membunuh bakteri'),
(9, 'Api unggun dalam kegiatan perkemahan memiliki fungsi utama sebagai...', '["A. Membelakangi atau menyamping dari arah hembusan angin utama","B. Sarana persaudaraan, kehangatan, dan pertunjukan seni","C. STOP (Stop, Think, Observe, Plan) dan tidak panik","D. Simpul Tali Tenda (Taut-line Hitch)"]', 'B. Sarana persaudaraan, kehangatan, dan pertunjukan seni'),
(9, 'Aturan utama dalam membuat api unggun di alam bebas agar tidak merusak lingkungan adalah...', '["A. 15-20 meter dari sumber air agar tidak mencemari mata air","B. Melakukan evaluasi kegiatan, membersihkan dan merawat kembali peralatan agar siap dipakai di kemudian hari","C. Membuat alas perapian (dari tanah/batu) atau tidak merusak area vegetasi di bawahnya","D. Pakaian berbahan katun/ripstop yang menyerap keringat, kuat, dan cepat kering (PDL)"]', 'C. Membuat alas perapian (dari tanah/batu) atau tidak merusak area vegetasi di bawahnya'),
(9, 'Pakaian lapangan yang ideal untuk berkemah adalah...', '["A. Disaring dengan kain lalu direbus hingga mendidih (matang) untuk membunuh bakteri","B. Pakaian berbahan katun/ripstop yang menyerap keringat, kuat, dan cepat kering (PDL)","C. Rawan tertimpa dahan atau pohon tumbang jika ada angin kencang","D. Miring 45-60 derajat berlawanan dengan arah tarikan tali tenda"]', 'B. Pakaian berbahan katun/ripstop yang menyerap keringat, kuat, dan cepat kering (PDL)'),
(9, 'Mengapa celana berbahan Jeans/Denim SANGAT TIDAK disarankan dipakai untuk kegiatan kemah di alam bebas?', '["A. Dikumpulkan dalam kantong sampah lalu dibawa turun/pulang (Pack it in, Pack it out)","B. Berat, tidak menyerap keringat, susah bergerak, dan sangat lama kering jika basah (bisa memicu hipotermia)","C. Membiarkan kondisi tapak kemah sama bersihnya atau lebih bersih daripada saat kita baru datang","D. Melakukan evaluasi kegiatan, membersihkan dan merawat kembali peralatan agar siap dipakai di kemudian hari"]', 'B. Berat, tidak menyerap keringat, susah bergerak, dan sangat lama kering jika basah (bisa memicu hipotermia)'),
(9, 'Jenis alas kaki yang paling aman untuk kegiatan perkemahan dan penjelajahan adalah...', '["A. 15-20 meter dari sumber air agar tidak mencemari mata air","B. Miring 45-60 derajat berlawanan dengan arah tarikan tali tenda","C. Sepatu lapangan/gunung yang menutupi mata kaki (Boot/Trekking Shoes)","D. Rawan tertimpa dahan atau pohon tumbang jika ada angin kencang"]', 'C. Sepatu lapangan/gunung yang menutupi mata kaki (Boot/Trekking Shoes)'),
(9, 'Lembaran kain sintetis kedap air yang sering dipasang di atas tenda untuk menahan air hujan atau dibuat sebagai atap teras dinamakan...', '["A. Flysheet","B. Hipotermia","C. Ponco","D. Tanda Jejak"]', 'A. Flysheet'),
(9, 'Alat kedap air yang diletakkan di bawah (lantai dasar) tenda agar uap air dari tanah tidak tembus ke dalam dinamakan...', '["A. Ponco","B. Groundsheet / Terpal","C. Tanda Jejak","D. Hipotermia"]', 'B. Groundsheet / Terpal'),
(9, 'Aturan keamanan saat memegang dan berjalan membawa senjata tajam (golok/pisau) di perkemahan adalah...', '["A. Melakukan evaluasi kegiatan, membersihkan dan merawat kembali peralatan agar siap dipakai di kemudian hari","B. Berat, tidak menyerap keringat, susah bergerak, dan sangat lama kering jika basah (bisa memicu hipotermia)","C. Memegang bagian gagang dengan sisi tajam menghadap ke belakang/bawah, atau dimasukkan ke dalam sarungnya","D. Membuat alas perapian (dari tanah/batu) atau tidak merusak area vegetasi di bawahnya"]', 'C. Memegang bagian gagang dengan sisi tajam menghadap ke belakang/bawah, atau dimasukkan ke dalam sarungnya'),
(9, 'Saat ada anggota yang bertugas piket jaga malam, posisi jaga yang paling benar adalah...', '["A. Menyusun Perencanaan dan Persiapan (surat izin, lokasi, anggaran)","B. Berjaga secara bergantian dan tidak jauh dari api/sumber cahaya darurat","C. Disaring dengan kain lalu direbus hingga mendidih (matang) untuk membunuh bakteri","D. 15-20 meter dari sumber air agar tidak mencemari mata air"]', 'B. Berjaga secara bergantian dan tidak jauh dari api/sumber cahaya darurat'),
(9, 'Jika tenda bocor parah di tengah hujan badai malam hari dan seluruh pakaian basah kuyup, ancaman kesehatan paling berbahaya adalah...', '["A. Tanda Jejak","B. Hipotermia","C. Ponco","D. Bivak"]', 'B. Hipotermia'),
(9, 'Etika perkemahan saat malam hari (Quiet Hours) mengharuskan seluruh anggota untuk...', '["A. Menghentikan aktivitas berisik dan beristirahat agar tidak mengganggu makhluk hidup dan tenda lain","B. Disaring dengan kain lalu direbus hingga mendidih (matang) untuk membunuh bakteri","C. Dikubur dalam lubang kecil yang tertutup rapat agak jauh dari tenda agar tidak mengundang hewan","D. Berat, tidak menyerap keringat, susah bergerak, dan sangat lama kering jika basah (bisa memicu hipotermia)"]', 'A. Menghentikan aktivitas berisik dan beristirahat agar tidak mengganggu makhluk hidup dan tenda lain'),
(9, 'Langkah pertama saat akan membongkar tenda di akhir kegiatan kemah adalah...', '["A. Menyalakan api, kompor, lentera minyak, atau lilin","B. Mengeluarkan dan membersihkan seluruh barang dari dalam tenda","C. Rawan tertimpa dahan atau pohon tumbang jika ada angin kencang","D. Obat penyakit khusus/alergi yang diidap oleh diri sendiri"]', 'B. Mengeluarkan dan membersihkan seluruh barang dari dalam tenda'),
(9, 'Syarat utama sebelum melipat kain tenda untuk disimpan ke dalam tas adalah...', '["A. Sangat berbahaya jika terjadi hujan lebat karena rawan banjir bandang/genangan air","B. Dekat dengan sumber air yang bersih dan aman dari bahaya alam","C. Tenda harus dalam keadaan benar-benar kering agar tidak berjamur","D. Obat penyakit khusus/alergi yang diidap oleh diri sendiri"]', 'C. Tenda harus dalam keadaan benar-benar kering agar tidak berjamur'),
(9, 'Prinsip pencinta alam "Leave No Trace" (Jangan tinggalkan jejak) mengajarkan kita untuk...', '["A. Melakukan evaluasi kegiatan, membersihkan dan merawat kembali peralatan agar siap dipakai di kemudian hari","B. Di luar tenda pada tempat terbuka dan aman dari tiupan angin kencang atau dedaunan kering","C. Membiarkan kondisi tapak kemah sama bersihnya atau lebih bersih daripada saat kita baru datang","D. Memegang bagian gagang dengan sisi tajam menghadap ke belakang/bawah, atau dimasukkan ke dalam sarungnya"]', 'C. Membiarkan kondisi tapak kemah sama bersihnya atau lebih bersih daripada saat kita baru datang'),
(9, 'Kotak atau tas darurat berukuran kecil berisi perlengkapan bertahan hidup esensial (seperti korek anti air, kail pancing, pisau lipat, plester) dinamakan...', '["A. Sleeping Bag (Kantong Tidur)","B. Survival Kit","C. Nesting","D. Ransel (Carrier / Backpack)"]', 'B. Survival Kit'),
(9, 'Tindakan yang benar jika tersesat saat melakukan kegiatan penjelajahan di sekitar perkemahan adalah...', '["A. Mencegah air hujan masuk/menggenangi bagian dalam tenda","B. STOP (Stop, Think, Observe, Plan) dan tidak panik","C. Rawan tertimpa dahan atau pohon tumbang jika ada angin kencang","D. Tenda harus dalam keadaan benar-benar kering agar tidak berjamur"]', 'B. STOP (Stop, Think, Observe, Plan) dan tidak panik'),
(9, 'Fungsi menggunakan pakaian lengan panjang saat menerobos semak/hutan di area kemah adalah...', '["A. Rawan tertimpa dahan atau pohon tumbang jika ada angin kencang","B. Menahan dingin, melindungi dari duri, goresan ranting, dan gigitan serangga","C. 15-20 meter dari sumber air agar tidak mencemari mata air","D. Pakaian ganti, sleeping bag, alat mandi, dan obat pribadi"]', 'B. Menahan dingin, melindungi dari duri, goresan ranting, dan gigitan serangga'),
(9, 'Tanda yang dibuat oleh anggota Pramuka menggunakan batu, ranting, atau goresan tanah untuk memberi petunjuk arah di alam bebas disebut...', '["A. Ransel (Carrier / Backpack)","B. Tanda Jejak","C. Sleeping Bag (Kantong Tidur)","D. Flysheet"]', 'B. Tanda Jejak'),
(9, 'Sikap mental yang paling dituntut dari seorang pemimpin regu saat perkemahan dilanda cuaca buruk adalah...', '["A. Membuat alas perapian (dari tanah/batu) atau tidak merusak area vegetasi di bawahnya","B. Berjaga secara bergantian dan tidak jauh dari api/sumber cahaya darurat","C. Tenang, mengambil keputusan cepat untuk mengamankan anggota, dan menjaga moral regu","D. Pakaian berbahan katun/ripstop yang menyerap keringat, kuat, dan cepat kering (PDL)"]', 'C. Tenang, mengambil keputusan cepat untuk mengamankan anggota, dan menjaga moral regu'),
(9, 'Obat yang wajib dibawa secara pribadi (tidak boleh mengandalkan regu) saat berkemah adalah...', '["A. Berjaga secara bergantian dan tidak jauh dari api/sumber cahaya darurat","B. Obat penyakit khusus/alergi yang diidap oleh diri sendiri","C. Menyalakan api, kompor, lentera minyak, atau lilin","D. Tenda harus dalam keadaan benar-benar kering agar tidak berjamur"]', 'B. Obat penyakit khusus/alergi yang diidap oleh diri sendiri'),
(9, 'Tujuan akhir setelah kembali dari kegiatan berkemah adalah...', '["A. Memegang bagian gagang dengan sisi tajam menghadap ke belakang/bawah, atau dimasukkan ke dalam sarungnya","B. Melakukan evaluasi kegiatan, membersihkan dan merawat kembali peralatan agar siap dipakai di kemudian hari","C. Berat, tidak menyerap keringat, susah bergerak, dan sangat lama kering jika basah (bisa memicu hipotermia)","D. Barang berat ditaruh di atas, barang ringan di bawah dan menempel punggung"]', 'B. Melakukan evaluasi kegiatan, membersihkan dan merawat kembali peralatan agar siap dipakai di kemudian hari'),

-- ==========================================
-- BAB 12: Sandi Morse (Komunikasi)
-- ==========================================
(12, 'Kata "Sandi" berasal dari bahasa Sanskerta, yang memiliki arti...', '["A. --..--","B. Rahasia","C. -.-.","D. Tiga garis (---)"]', 'B. Rahasia'),
(12, 'Fungsi utama mempelajari sandi dalam kegiatan kepramukaan adalah untuk...', '["A. Berlawanan / Berkebalikan (Contoh: A >< N)","B. Melatih daya ingat, kecerdasan, dan ketelitian","C. Garis miring ganda (//)","D. .--."]', 'B. Melatih daya ingat, kecerdasan, dan ketelitian'),
(12, 'Penemu sistem telegraf dan kode Morse adalah seorang seniman dan penemu asal Amerika yang bernama...', '["A. --.-","B. Samuel F.B. Morse","C. ..-.","D. -.-"]', 'B. Samuel F.B. Morse'),
(12, 'Kode Morse pertama kali ditemukan dan digunakan secara praktis pada tahun...', '["A. 1837","B. 1839","C. 1832","D. 1840"]', 'A. 1837'),
(12, 'Dalam standar internasional, perbandingan durasi waktu antara bunyi/simbol "titik" dan "garis" pada sandi Morse adalah...', '["A. .----","B. 1 : 3","C. .-...","D. .--"]', 'B. 1 : 3'),
(12, 'Huruf yang direpresentasikan dengan satu titik (.) dalam sandi Morse adalah...', '["A. T","B. E","C. .-","D. Tiga garis (---)"]', 'B. E'),
(12, 'Huruf yang direpresentasikan dengan satu garis (-) dalam sandi Morse adalah...', '["A. --..","B. --.","C. T","D. 3"]', 'C. T'),
(12, 'Kode Morse untuk huruf "A" adalah...', '["A. .-","B. -.","C. ..","D. --"]', 'A. .-'),
(12, 'Kode Morse untuk huruf "B" adalah...', '["A. -...","B. .-.-","C. --..","D. .---"]', 'A. -...'),
(12, 'Sinyal marabahaya darurat atau minta tolong standar internasional (SOS) dalam sandi Morse ditulis dengan...', '["A. .-- ..- ---","B. ... --- ...","C. ... --. ..-","D. .-- -.. .--"]', 'B. ... --- ...'),
(12, 'Kode Morse (...--) melambangkan angka...', '["A. 8","B. 7","C. 3","D. 1"]', 'C. 3'),
(12, 'Kode Morse (---..) melambangkan angka...', '["A. 12","B. 7","C. 8","D. 11"]', 'C. 8'),
(12, 'Kode Morse (----.) melambangkan angka...', '["A. 8","B. 6","C. 9","D. 12"]', 'C. 9'),
(12, 'Tanda pemisah antar kata saat menulis sandi Morse di atas kertas biasanya menggunakan tanda...', '["A. Samuel F.B. Morse","B. Garis miring ganda (//)","C. Tiga titik (...)","D. Darurat / Marabahaya"]', 'B. Garis miring ganda (//)'),
(12, 'Dalam pengiriman pesan Morse, tanda untuk memulai panggilan atau "Attention" biasanya menggunakan kode...', '["A. -.-.-.","B. ....-.","C. .---.-","D. ......"]', 'A. -.-.-.'),
(12, 'Isyarat bahwa "Pesan Selesai" (End of Message) dalam pengiriman Morse ditandai dengan kode gabungan huruf AR, yaitu...', '["A. .-.-.","B. -..-.","C. .---.","D. -----"]', 'A. .-.-.'),
(12, 'Jika pengirim melakukan kesalahan saat mengirim sandi Morse, ia memberikan isyarat salah (E 8 kali) yang berbunyi...', '["A. -.---.-.","B. ........","C. -..---..","D. ....-..-"]', 'B. ........'),
(12, 'Huruf yang secara kode berlawanan dengan A (.-) adalah N, yaitu...', '["A. -.","B. --","C. .-","D. .."]', 'A. -.'),
(12, 'Huruf "O" dalam sandi Morse terdiri dari...', '["A. Tiga garis (---)","B. Rahasia","C. -.","D. ...-"]', 'A. Tiga garis (---)'),
(12, 'Huruf "S" dalam sandi Morse terdiri dari...', '["A. Tiga titik (...)","B. -..","C. ... --- ...","D. ...-"]', 'A. Tiga titik (...)'),
(12, 'Gabungan huruf S dan O membentuk kata SOS, yang secara universal berarti isyarat...', '["A. -.-","B. Darurat / Marabahaya","C. Samuel F.B. Morse","D. ..--.."]', 'B. Darurat / Marabahaya'),
(12, 'Huruf "I" dalam sandi Morse terdiri dari...', '["A. ..-.","B. 9","C. Dua titik (..)","D. Samuel F.B. Morse"]', 'C. Dua titik (..)'),
(12, 'Huruf "M" dalam sandi Morse terdiri dari...', '["A. ........","B. Dua garis (--)","C. .-...","D. -.--"]', 'B. Dua garis (--)'),
(12, 'Huruf "C" dalam sandi Morse dituliskan dengan kode...', '["A. -.-.","B. --.-","C. ..--","D. --.."]', 'A. -.-.'),
(12, 'Huruf "D" dalam sandi Morse dituliskan dengan kode...', '["A. -.-","B. -..","C. --.","D. .--"]', 'B. -..'),
(12, 'Berlawanan dengan huruf D (-..), huruf "U" dalam sandi morse adalah...', '["A. ..-","B. ---","C. -.-","D. .--"]', 'A. ..-'),
(12, 'Huruf "F" dalam sandi Morse adalah...', '["A. ..-.","B. -.-.","C. -.--","D. -..."]', 'A. ..-.'),
(12, 'Huruf "G" dalam sandi Morse adalah...', '["A. ...","B. --.","C. .--","D. -.."]', 'B. --.'),
(12, 'Huruf "H" dalam sandi Morse adalah...', '["A. .--.","B. .---","C. ..-.","D. ...."]', 'D. ....'),
(12, 'Huruf "J" dalam sandi Morse adalah...', '["A. -..-","B. -...","C. .---","D. --.."]', 'C. .---'),
(12, 'Huruf "K" dalam sandi Morse adalah...', '["A. -.-","B. .-.","C. --.","D. ..-"]', 'A. -.-'),
(12, 'Huruf "L" dalam sandi Morse adalah...', '["A. .-.-","B. .-..","C. -.--","D. ----"]', 'B. .-..'),
(12, 'Huruf "P" dalam sandi Morse adalah...', '["A. ....","B. -.--","C. .--.","D. -..."]', 'C. .--.'),
(12, 'Huruf "Q" dalam sandi Morse adalah...', '["A. --.-","B. -...","C. ...-","D. ...."]', 'A. --.-'),
(12, 'Huruf "R" dalam sandi Morse adalah...', '["A. -..","B. .-.","C. ...","D. ---"]', 'B. .-.'),
(12, 'Huruf "V" dalam sandi Morse adalah...', '["A. .-..","B. -.--","C. ...-","D. ..--"]', 'C. ...-'),
(12, 'Huruf "W" dalam sandi Morse adalah...', '["A. .--","B. -..","C. -.-","D. ..."]', 'A. .--'),
(12, 'Huruf "X" dalam sandi Morse adalah...', '["A. --..","B. -..-","C. .--.","D. -.--"]', 'B. -..-'),
(12, 'Huruf "Y" dalam sandi Morse adalah...', '["A. .--.","B. --.-","C. -.--","D. ----"]', 'C. -.--'),
(12, 'Huruf "Z" dalam sandi Morse adalah...', '["A. --..","B. ---.","C. ----","D. .-.."]', 'A. --..'),
(12, 'Angka 1 dalam sandi Morse ditulis dengan urutan...', '["A. .--..","B. .----","C. -..-.","D. ....-"]', 'B. .----'),
(12, 'Angka 5 dalam sandi Morse adalah...', '["A. .----","B. -.---","C. .....","D. .-..."]', 'C. .....'),
(12, 'Angka 0 dalam sandi Morse adalah...', '["A. -----","B. --...","C. ..-.-","D. -...-"]', 'A. -----'),
(12, 'Tanda koma (,) dalam tulisan Morse diwakili dengan gabungan...', '["A. -...-.","B. --..--","C. .----.","D. ..-.-."]', 'B. --..--'),
(12, 'Tanda tanya (?) dalam tulisan Morse diwakili dengan gabungan...', '["A. ..--..","B. --.-..","C. -.-.-.","D. ---.--"]', 'A. ..--..'),
(12, 'Saat mengirim kode Morse dengan peluit, bunyi tiupan pendek secara internasional mewakili...', '["A. Titik","B. T","C. .--.","D. -..."]', 'A. Titik'),
(12, 'Saat mengirim kode Morse dengan peluit, bunyi tiupan panjang yang keras mewakili...', '["A. .--.","B. Garis","C. .....","D. ...."]', 'B. Garis'),
(12, 'Isyarat komunikasi "Tunggu" (AS) yang dikirimkan kepada lawan saat transmisi Morse adalah...', '["A. ---.-","B. ---..","C. .-...","D. .---."]', 'C. .-...'),
(12, 'Isyarat "Mengerti / Pesan Diterima" (R) yang dikirimkan kembali oleh penerima pesan adalah...', '["A. .-.","B. ...","C. -.-","D. .--"]', 'A. .-.'),
(12, 'Cara paling mudah dan umum yang diajarkan dalam pramuka untuk menghafal sandi Morse adalah metode pengelompokan huruf yang saling...', '["A. Melatih daya ingat, kecerdasan, dan ketelitian","B. Berlawanan / Berkebalikan (Contoh: A >< N)","C. .--.","D. Garis"]', 'B. Berlawanan / Berkebalikan (Contoh: A >< N)'),

-- ==========================================
-- BAB 15: Membaca Peta & Navigasi
-- ==========================================
(15, 'Gambar seluruh atau sebagian permukaan bumi yang diproyeksikan pada bidang datar dengan perbandingan skala tertentu disebut...', '["A. Peta Topografi","B. Peta","C. Indeks Kontur","D. Deklinasi Magnetis"]', 'B. Peta'),
(15, 'Jenis peta yang sangat penting bagi Pramuka karena menggambarkan tinggi rendahnya permukaan bumi (relief) secara detail adalah...', '["A. Northing","B. Peta Topografi","C. 60 menit","D. Landai / Datar"]', 'B. Peta Topografi'),
(15, 'Kumpulan penjelasan tentang arti simbol-simbol dan warna yang terdapat pada peta disebut...', '["A. 250 meter","B. Atlas","C. LU (N - North)","D. Legenda Peta"]', 'D. Legenda Peta'),
(15, 'Angka yang menunjukkan perbandingan antara jarak di atas peta dengan jarak sebenarnya di lapangan disebut...', '["A. Deklinasi Magnetis","B. Landai / Datar","C. Skala","D. Interval Kontur"]', 'C. Skala'),
(15, 'Peta dengan skala 1 : 25.000 berarti 1 cm pada peta mewakili jarak sebenarnya di lapangan sejauh...', '["A. 255 meter","B. 250 meter","C. 251 meter","D. 254 meter"]', 'B. 250 meter'),
(15, 'Jika jarak antara titik A dan B di peta topografi (skala 1:50.000) adalah 4 cm, maka jarak sebenarnya di lapangan adalah...', '["A. 4 kilometer","B. 2 kilometer","C. 6 kilometer","D. 7 kilometer"]', 'B. 2 kilometer'),
(15, 'Skala peta yang ditunjukkan dalam bentuk garis lurus yang terbagi menjadi beberapa ruas dengan ukuran satuan jarak tertentu disebut...', '["A. Deklinasi Magnetis","B. Sundial / Metode Bayangan Matahari","C. Skala Garis (Grafis)","D. 60 menit"]', 'C. Skala Garis (Grafis)'),
(15, 'Garis khayal melingkar pada peta topografi yang menghubungkan titik-titik dengan ketinggian yang sama dari permukaan laut disebut...', '["A. Legenda Peta","B. LU (N - North)","C. Garis Kontur","D. Protractor (Busur Peta)"]', 'C. Garis Kontur'),
(15, 'Ciri khas utama dari garis kontur adalah jika jarak antar garisnya tergambar sangat rapat, hal itu menunjukkan bentuk medan yang...', '["A. Orientasi Peta","B. Curam / Terjal","C. Indeks Kontur","D. Peta Topografi"]', 'B. Curam / Terjal'),
(15, 'Jika jarak antar garis kontur di peta terlihat renggang atau saling berjauhan, itu menandakan bentuk medan yang...', '["A. 100 meter persegi","B. Greenwich, London, Inggris","C. Landai / Datar","D. Lembah / Aliran Sungai"]', 'C. Landai / Datar'),
(15, 'Garis kontur yang membentuk pola huruf "V" atau "U" terbalik yang menjorok ke arah ketinggian (menunjuk ke tempat yang lebih tinggi) menandakan bentang alam berupa...', '["A. 0 derajat lintang","B. Lembah / Aliran Sungai","C. Garis Kontur","D. Deklinasi Magnetis"]', 'B. Lembah / Aliran Sungai'),
(15, 'Garis kontur yang membentuk pola huruf "V" atau "U" yang menjorok ke arah tempat yang lebih rendah menandakan bentang alam berupa...', '["A. Utara Peta (Grid North)","B. Punggungan (Sadel) / Punggung Bukit","C. Menghitung jumlah langkah kaki ganda (Pacing)","D. Sundial / Metode Bayangan Matahari"]', 'B. Punggungan (Sadel) / Punggung Bukit'),
(15, 'Garis kontur yang tergambar berupa lingkaran-lingkaran kecil konsentris yang semakin mengecil di bagian tengah biasanya menandakan...', '["A. Puncak bukit / Gunung","B. Landai / Datar","C. Skala Garis (Grafis)","D. Kawasan vegetasi / Hutan / Perkebunan"]', 'A. Puncak bukit / Gunung'),
(15, 'Jika ada garis kontur melingkar namun memiliki garis-garis rambut kecil (tick marks) yang mengarah ke bagian dalam lingkaran, itu menandakan...', '["A. Utara Sebenarnya (True North)","B. LU (N - North)","C. Depresi / Kawah / Cekungan","D. Kawasan vegetasi / Hutan / Perkebunan"]', 'C. Depresi / Kawah / Cekungan'),
(15, 'Selisih ketinggian atau jarak vertikal antara satu garis kontur dengan garis kontur di sebelahnya disebut...', '["A. Atlas","B. Interval Kontur","C. 250 meter","D. 2 kilometer"]', 'B. Interval Kontur'),
(15, 'Garis kontur yang biasanya dicetak lebih tebal dan disertai angka penunjuk ketinggian untuk mempermudah pembacaan peta disebut...', '["A. Greenwich, London, Inggris","B. 60 menit","C. Indeks Kontur","D. 2 kilometer"]', 'C. Indeks Kontur'),
(15, 'Sistem garis kisi-kisi (grid) yang membagi peta menjadi kotak-kotak untuk menentukan posisi secara akurat dinamakan koordinat...', '["A. Sundial / Metode Bayangan Matahari","B. Melakukan Orientasi Peta terlebih dahulu","C. UTM (Universal Transverse Mercator)","D. Utara Peta (Grid North)"]', 'C. UTM (Universal Transverse Mercator)'),
(15, 'Garis vertikal (membujur dari bawah ke atas) pada sistem koordinat kotak (grid) peta yang angkanya dibaca pertama kali (dibaca ke arah Timur) disebut...', '["A. Atlas","B. Easting","C. Northing","D. Peta Topografi"]', 'B. Easting'),
(15, 'Garis horizontal (melintang dari kiri ke kanan) pada sistem koordinat grid peta yang angkanya dibaca kedua (dibaca ke arah Utara) disebut...', '["A. Curvimeter","B. Northing","C. 250 meter","D. Legenda Peta"]', 'B. Northing'),
(15, 'Aturan emas (golden rule) dalam membaca koordinat grid di atas peta topografi adalah...', '["A. Dilipat seperti kipas / akordion (zig-zag) dengan bagian yang akan dibaca menghadap luar","B. Karena sisi tersebut paling sedikit/banyak terkena paparan sinar matahari langsung (kondisi lembap)","C. Baca dari kiri ke kanan (Easting), lalu dari bawah ke atas (Northing)","D. Puncak bukit / Gunung"]', 'C. Baca dari kiri ke kanan (Easting), lalu dari bawah ke atas (Northing)'),
(15, 'Jika kita diminta menunjuk titik dengan koordinat 6 digit (contoh: 456 789), ini berarti tingkat ketelitian pencarian lokasi tersebut mencapai area seluas...', '["A. 2 kilometer","B. 100 meter persegi","C. Resection","D. Depresi / Kawah / Cekungan"]', 'B. 100 meter persegi'),
(15, 'Arah Utara yang ditunjukkan oleh garis-garis grid vertikal lurus ke atas pada peta disebut...', '["A. Legenda Peta","B. Interval Kontur","C. Utara Peta (Grid North)","D. Protractor (Busur Peta)"]', 'C. Utara Peta (Grid North)'),
(15, 'Arah Utara yang mengarah tepat ke Kutub Utara bumi (poros rotasi) disebut...', '["A. Peta Topografi","B. Kawasan vegetasi / Hutan / Perkebunan","C. Utara Sebenarnya (True North)","D. 250 meter"]', 'C. Utara Sebenarnya (True North)'),
(15, 'Dalam legenda peta topografi standar, warna COKLAT umumnya digunakan untuk menggambarkan...', '["A. Depresi / Kawah / Cekungan","B. Punggungan (Sadel) / Punggung Bukit","C. Garis ketinggian (Kontur) dan bentang alam darat","D. Kawasan vegetasi / Hutan / Perkebunan"]', 'C. Garis ketinggian (Kontur) dan bentang alam darat'),
(15, 'Warna HIJAU pada peta topografi selalu mengindikasikan adanya...', '["A. GPS (Global Positioning System)","B. Kawasan vegetasi / Hutan / Perkebunan","C. Ursa Major (Bintang Biduk) / Polaris","D. Hidrografi / Perairan (Sungai, danau, rawa, laut)"]', 'B. Kawasan vegetasi / Hutan / Perkebunan'),
(15, 'Warna BIRU pada peta digunakan secara universal untuk menyimbolkan unsur...', '["A. Bagian tepi bawah luar / Margin bawah peta","B. Sundial / Metode Bayangan Matahari","C. Hidrografi / Perairan (Sungai, danau, rawa, laut)","D. U atau V terbalik (menjorok ke bawah)"]', 'C. Hidrografi / Perairan (Sungai, danau, rawa, laut)'),
(15, 'Warna MERAH pada peta topografi sering kali dikhususkan untuk menandakan unsur penting buatan manusia, yaitu...', '["A. Curam / Terjal","B. Jalan raya utama / aspal","C. Garis ketinggian (Kontur) dan bentang alam darat","D. Skala Garis (Grafis)"]', 'B. Jalan raya utama / aspal'),
(15, 'Warna HITAM dalam peta biasanya digunakan untuk mencetak...', '["A. Hidrografi / Perairan (Sungai, danau, rawa, laut)","B. U atau V terbalik (menjorok ke bawah)","C. Simbol pemukiman, gedung, jalan setapak, dan tulisan","D. Garis ketinggian (Kontur) dan bentang alam darat"]', 'C. Simbol pemukiman, gedung, jalan setapak, dan tulisan'),
(15, 'Simbol berupa titik hitam dengan bentuk segitiga atau lingkaran disertai angka (misal: ▲ 2100) di peta menunjukkan...', '["A. Melakukan Orientasi Peta terlebih dahulu","B. Titik Triangulasi / Ketinggian mutlak (Spot Height)","C. Ursa Major (Bintang Biduk) / Polaris","D. U atau V terbalik (menjorok ke bawah)"]', 'B. Titik Triangulasi / Ketinggian mutlak (Spot Height)'),
(15, 'Tindakan menyamakan posisi arah Utara pada peta agar sejajar dengan arah Utara sebenarnya di lapangan (menggunakan kompas) disebut...', '["A. Orientasi Peta","B. Easting","C. Utara Peta (Grid North)","D. Curvimeter"]', 'A. Orientasi Peta'),
(15, 'Syarat pertama yang harus dilakukan sebelum melakukan teknik navigasi Resection atau Intersection di lapangan adalah...', '["A. U atau V terbalik (menjorok ke bawah)","B. Melakukan Orientasi Peta terlebih dahulu","C. Ursa Major (Bintang Biduk) / Polaris","D. Depresi / Kawah / Cekungan"]', 'B. Melakukan Orientasi Peta terlebih dahulu'),
(15, 'Teknik navigasi untuk menentukan titik koordinat posisi kita sendiri di atas peta, dengan cara membidik dua objek alam yang sudah diketahui di peta, disebut...', '["A. Northing","B. Interval Kontur","C. Resection","D. Orientasi Peta"]', 'C. Resection'),
(15, 'Teknik navigasi untuk mencari koordinat posisi objek lain (sasaran) yang belum diketahui di peta, dengan membidiknya dari dua titik stasiun yang berbeda, disebut...', '["A. Easting","B. Intersection","C. Curam / Terjal","D. Garis Kontur"]', 'B. Intersection'),
(15, 'Alat ukur sederhana berbentuk busur derajat berbentuk kotak persegi transparan yang digunakan untuk menghitung sudut dan koordinat langsung di atas peta disebut...', '["A. Punggungan (Sadel) / Punggung Bukit","B. LU (N - North)","C. 250 meter","D. Protractor (Busur Peta)"]', 'D. Protractor (Busur Peta)'),
(15, 'Alat mekanis kecil dengan roda bergerigi yang dijalankan menyusuri rute lengkung di peta (seperti sungai atau jalan berliku) untuk menghitung jarak disebut...', '["A. Curvimeter","B. 0 derajat lintang","C. Atlas","D. Landai / Datar"]', 'A. Curvimeter'),
(15, 'Penyimpangan sudut yang terjadi antara garis Utara Peta (Grid) dengan Utara Magnetis (Kompas) di suatu wilayah disebut...', '["A. Deklinasi Magnetis","B. Skala Garis (Grafis)","C. Interval Kontur","D. Puncak bukit / Gunung"]', 'A. Deklinasi Magnetis'),
(15, 'Jika kita melipat peta topografi untuk dibawa di saku lapangan, cara melipat yang benar agar peta tidak cepat rusak dan mudah dibaca adalah...', '["A. Karena sisi tersebut paling sedikit/banyak terkena paparan sinar matahari langsung (kondisi lembap)","B. Baca dari kiri ke kanan (Easting), lalu dari bawah ke atas (Northing)","C. Dilipat seperti kipas / akordion (zig-zag) dengan bagian yang akan dibaca menghadap luar","D. Deklinasi Magnetis"]', 'C. Dilipat seperti kipas / akordion (zig-zag) dengan bagian yang akan dibaca menghadap luar'),
(15, 'Saat membaca peta, jika kita berjalan mengikuti punggungan bukit (ridge), maka di peta kita sebenarnya sedang melangkah memotong garis-garis kontur yang berbentuk...', '["A. Kawasan vegetasi / Hutan / Perkebunan","B. U atau V terbalik (menjorok ke bawah)","C. Simbol pemukiman, gedung, jalan setapak, dan tulisan","D. Melakukan Orientasi Peta terlebih dahulu"]', 'B. U atau V terbalik (menjorok ke bawah)'),
(15, 'Kumpulan peta dalam satu wujud buku besar dinamakan...', '["A. Atlas","B. Garis Kontur","C. 100 meter persegi","D. Peta"]', 'A. Atlas'),
(15, 'Jika tidak memiliki meteran, seorang Pramuka dapat memperkirakan jarak di peta dengan di lapangan menggunakan teknik...', '["A. Menghitung jumlah langkah kaki ganda (Pacing)","B. Depresi / Kawah / Cekungan","C. Bagian tepi bawah luar / Margin bawah peta","D. Simbol pemukiman, gedung, jalan setapak, dan tulisan"]', 'A. Menghitung jumlah langkah kaki ganda (Pacing)'),
(15, 'Garis Khatulistiwa (Equator) yang membelah bumi menjadi Utara dan Selatan ditarik pada derajat...', '["A. 0 derajat lintang","B. Melakukan Orientasi Peta terlebih dahulu","C. Curvimeter","D. Utara Peta (Grid North)"]', 'A. 0 derajat lintang'),
(15, 'Garis Bujur Utama (Prime Meridian) yang menjadi titik 0 derajat dan patokan waktu bumi disepakati melintasi kota...', '["A. 250 meter","B. Selatan","C. Greenwich, London, Inggris","D. Melakukan Orientasi Peta terlebih dahulu"]', 'C. Greenwich, London, Inggris'),
(15, 'Informasi mengenai tahun pembuatan atau pembaruan peta (update) biasanya dapat ditemukan di...', '["A. U atau V terbalik (menjorok ke bawah)","B. Hidrografi / Perairan (Sungai, danau, rawa, laut)","C. Bagian tepi bawah luar / Margin bawah peta","D. Simbol pemukiman, gedung, jalan setapak, dan tulisan"]', 'C. Bagian tepi bawah luar / Margin bawah peta'),
(15, 'Navigasi yang dilakukan di malam hari tanpa kompas dapat mengandalkan Rasi Bintang Pari (Crux) untuk menentukan arah...', '["A. Interval Kontur","B. Selatan","C. 60 menit","D. Curvimeter"]', 'B. Selatan'),
(15, 'Navigasi malam hari di belahan bumi utara/tengah dapat menentukan arah Utara dengan mencari konstelasi bintang...', '["A. Ursa Major (Bintang Biduk) / Polaris","B. Kawasan vegetasi / Hutan / Perkebunan","C. UTM (Universal Transverse Mercator)","D. Jalan raya utama / aspal"]', 'A. Ursa Major (Bintang Biduk) / Polaris'),
(15, 'Alasan mengapa lumut pada pohon lebih sering tumbuh tebal di sisi tertentu (sebagai navigasi darurat penunjuk Timur/Barat) adalah...', '["A. Baca dari kiri ke kanan (Easting), lalu dari bawah ke atas (Northing)","B. Karena sisi tersebut paling sedikit/banyak terkena paparan sinar matahari langsung (kondisi lembap)","C. Dilipat seperti kipas / akordion (zig-zag) dengan bagian yang akan dibaca menghadap luar","D. Melakukan Orientasi Peta terlebih dahulu"]', 'B. Karena sisi tersebut paling sedikit/banyak terkena paparan sinar matahari langsung (kondisi lembap)'),
(15, 'Metode navigasi alam menggunakan bayangan tongkat kayu yang ditancapkan tegak di tanah pada siang hari disebut metode...', '["A. Greenwich, London, Inggris","B. Sundial / Metode Bayangan Matahari","C. Curam / Terjal","D. Ursa Major (Bintang Biduk) / Polaris"]', 'B. Sundial / Metode Bayangan Matahari'),
(15, 'Pada peta dengan sistem koordinat grid geografis, Lintang Utara disingkat dengan huruf...', '["A. LU (N - North)","B. GPS (Global Positioning System)","C. Kawasan vegetasi / Hutan / Perkebunan","D. Legenda Peta"]', 'A. LU (N - North)'),
(15, 'Satu derajat (1°) dalam sistem koordinat Geografis (DMS) dibagi lagi menjadi...', '["A. 65 menit","B. 60 menit","C. 56 menit","D. 58 menit"]', 'B. 60 menit'),
(15, 'Sistem Penentuan Posisi Global yang mengandalkan perangkat elektronik untuk menerima sinyal satelit navigasi bumi disebut...', '["A. Jalan raya utama / aspal","B. Utara Sebenarnya (True North)","C. GPS (Global Positioning System)","D. Peta Topografi"]', 'C. GPS (Global Positioning System)'),

-- ==========================================
-- BAB 20: Macam-Macam Sandi
-- ==========================================
(20, 'Sandi yang menggunakan bentuk garis vertikal, horizontal, dan titik sebagai pengganti huruf disebut...', '["A. Sandi Arab","B. Sandi Kotak 1","C. 07.10","D. 1 titik"]', 'B. Sandi Kotak 1'),
(20, 'Sandi Kotak 1 terdiri dari dua macam bentuk pola kerangka dasar, yaitu...', '["A. Tanda Garis (-) pada Morse","B. Palang tegak lurus dan silang (X)","C. 10 huruf tanpa ada huruf ganda yang sama","D. Tanda Titik (.) pada Morse"]', 'B. Palang tegak lurus dan silang (X)'),
(20, 'Dalam Sandi Kotak 1, masing-masing ruangan kotak pada kerangka palang maksimal diisi oleh...', '["A. 7 huruf","B. 2 huruf","C. 3 huruf","D. 4 huruf"]', 'B. 2 huruf'),
(20, 'Dalam Sandi Kotak 1, huruf "B" digambarkan dengan bentuk sudut siku-siku terbuka ke atas-kanan, ditambah dengan...', '["A. 5 titik","B. 1 titik","C. 2 titik","D. 3 titik"]', 'B. 1 titik'),
(20, 'Dalam Sandi Kotak 1, huruf "A" digambarkan dengan bentuk sudut siku-siku terbuka ke atas-kanan, ditambah dengan...', '["A. Tanpa titik","B. Sandi Siput","C. Baris pertama","D. KIZNFPZ"]', 'A. Tanpa titik'),
(20, 'Dalam Sandi Kotak 1, huruf "N" yang berada di kerangka silang (X) digambarkan dengan bentuk huruf V yang terbuka ke bawah, ditambah dengan...', '["A. Tanpa titik","B. Sandi Koordinat","C. Huruf Konsonan, contohnya K","D. PRAMUKA"]', 'A. Tanpa titik'),
(20, 'Perbedaan utama antara Sandi Kotak 1 dan Sandi Kotak 2 (versi Boyman) terletak pada penempatan huruf, yaitu...', '["A. Mengirim pesan rahasia di masa perang/kritis agar tidak dapat dibaca oleh pihak musuh","B. Setiap kotak pada Sandi Kotak 2 berisi 3 huruf dan maksimal menggunakan 2 titik","C. C","D. Tanda Titik (.) pada Morse"]', 'B. Setiap kotak pada Sandi Kotak 2 berisi 3 huruf dan maksimal menggunakan 2 titik'),
(20, 'Dalam Sandi Kotak 2, huruf "C" ditandai dengan kotak yang sama dengan huruf A dan B, namun dibedakan menggunakan...', '["A. 2 huruf","B. PRAMUKA","C. Menggunakan 2 titik","D. OH"]', 'C. Menggunakan 2 titik'),
(20, 'Sandi Kotak 3 memiliki bentuk dasar kerangka yang unik dan sedikit rumit, yaitu berbentuk susunan...', '["A. Tanda Titik (.) pada Morse","B. Belah ketupat (segi empat silang)","C. Morse dan Semaphore","D. Huruf Konsonan, contohnya K"]', 'B. Belah ketupat (segi empat silang)'),
(20, 'Sandi Rumput pada dasarnya merupakan bentuk kamuflase atau aplikasi visual murni dari...', '["A. Sandi AN","B. 45 x 45 cm","C. Sandi Morse","D. 2 huruf"]', 'C. Sandi Morse'),
(20, 'Pada Sandi Rumput, lambang titik (.) pada kode morse digambarkan dengan wujud...', '["A. C","B. Rumput pendek","C. CENZHXN","D. 07.10"]', 'B. Rumput pendek'),
(20, 'Pada Sandi Rumput, lambang garis (-) pada kode morse digambarkan dengan wujud...', '["A. Rumput tinggi","B. Sandi Siput","C. Sandi Kimia","D. Sandi Arab"]', 'A. Rumput tinggi'),
(20, 'Sandi yang mengubah urutan abjad sedemikian rupa sehingga abjad dibagi dua, huruf "A" dibaca "N", "B" dibaca "O", dan seterusnya, disebut...', '["A. Sandi Arab","B. Sandi AN","C. 07.10","D. C"]', 'B. Sandi AN'),
(20, 'Kata "PRAMUKA" jika dipecahkan menggunakan rumus abjad Sandi AN akan berbunyi...', '["A. CENZHXN","B. 07.10","C. Morse dan Semaphore","D. Rumput pendek"]', 'A. CENZHXN'),
(20, 'Sandi yang menukar huruf awal alfabet dengan huruf akhir (A menjadi Z, B menjadi Y, C menjadi X) disebut...', '["A. Sandi AZ / Sandi Balik Abjad","B. Belah ketupat (segi empat silang)","C. Tanda Garis (-) pada Morse","D. Sandi Ular / Sandi Gergaji"]', 'A. Sandi AZ / Sandi Balik Abjad'),
(20, 'Kata "PRAMUKA" jika dibaca ke dalam rumus Sandi AZ maka akan menjadi susunan huruf...', '["A. Rumput tinggi","B. KIZNFPZ","C. Sandi Siput","D. Semaphore"]', 'B. KIZNFPZ'),
(20, 'Dalam Sandi Angka dasar, di mana A=1, B=2, dst., maka susunan kode 16-18-1-13-21-11-1 dibaca...', '["A. Morse dan Semaphore","B. MERAH PUTIH","C. PRAMUKA","D. Baris pertama"]', 'C. PRAMUKA'),
(20, 'Sandi Angka juga bisa divariasikan patokannya (misal awalan A=0). Jika A=0, maka huruf C adalah angka...', '["A. 6","B. 4","C. 2","D. 5"]', 'C. 2'),
(20, 'Sandi yang pengerjaannya menggunakan dua kata kunci yang digabungkan membentuk tabel baris dan kolom persilangan, disebut...', '["A. C","B. Sandi Koordinat","C. 1 titik","D. Rumput tinggi"]', 'B. Sandi Koordinat'),
(20, 'Dua buah kata yang paling sering dan umum dijadikan kata kunci dalam Sandi Koordinat Pramuka adalah...', '["A. MERAH PUTIH","B. Huruf Vokal, contohnya O","C. Sandi Kotak 1","D. Sandi AND"]', 'A. MERAH PUTIH'),
(20, 'Dalam Sandi Koordinat "MERAH PUTIH", huruf "M" mewakili posisi...', '["A. C","B. Baris pertama","C. 2","D. Sandi AND"]', 'B. Baris pertama'),
(20, 'Sandi yang memanfaatkan patokan interval selisih waktu secara berurutan sebagai pengganti abjad alfabet disebut...', '["A. C","B. PRAMUKA","C. Sandi Jam","D. Rahasia"]', 'C. Sandi Jam'),
(20, 'Pada Sandi Jam, jika disepakati pukul 08.00 adalah huruf A, dan interval beda waktu adalah 5 menit, maka huruf B ditulis pada...', '["A. Sandi Koordinat","B. 08.05","C. CENZHXN","D. Sandi Arab"]', 'B. 08.05'),
(20, 'Jika pukul 07.00 = A dengan interval waktu yang sama yaitu 5 menit, jam berapakah yang akan menunjukkan huruf C?', '["A. 1 titik","B. 07.10","C. Sandi Kimia","D. Louis Braille"]', 'B. 07.10'),
(20, 'Sandi yang mengadopsi cara penulisan unsur rumus kimia, dan sebenarnya merupakan kamuflase lain dari sandi Morse, disebut...', '["A. Sandi Kotak 1","B. Rumput pendek","C. Sandi Kimia","D. Semaphore"]', 'C. Sandi Kimia'),
(20, 'Dalam ketentuan Sandi Kimia Pramuka, kelompok huruf Vokal (A, I, U, E, O) berfungsi menggantikan posisi...', '["A. Tanda Titik (.) pada Morse","B. Belah ketupat (segi empat silang)","C. Morse dan Semaphore","D. Sandi Kotak 1"]', 'A. Tanda Titik (.) pada Morse'),
(20, 'Dalam Sandi Kimia, kelompok huruf Konsonan (B, C, D, F, dst) berfungsi menggantikan posisi...', '["A. Morse dan Semaphore","B. Tanda Garis (-) pada Morse","C. Huruf Konsonan, contohnya K","D. Huruf Vokal, contohnya O"]', 'B. Tanda Garis (-) pada Morse'),
(20, 'Kode Morse ".-" (Huruf A) jika diubah ke dalam Sandi Kimia bisa ditulis menjadi wujud kombinasi Vokal-Konsonan bebas, misalnya...', '["A. OH","B. 07.10","C. Sandi AND","D. Rumput tinggi"]', 'A. OH'),
(20, 'Sandi kata yang cara menyembunyikannya adalah dengan menyisipkan huruf/kata "AND" di antara abjad aslinya disebut...', '["A. Morse dan Semaphore","B. Sandi Morse","C. Sandi AND","D. Baris pertama"]', 'C. Sandi AND'),
(20, 'Sandi yang bentuk aslinya menyerupai lekukan garis-garis bergelombang tak terputus, di mana lekukan kecil adalah titik dan lekukan besar/runcing adalah garis, dinamakan...', '["A. Huruf Konsonan, contohnya K","B. Sandi AZ / Sandi Balik Abjad","C. 45 x 45 cm","D. Sandi Ular / Sandi Gergaji"]', 'D. Sandi Ular / Sandi Gergaji'),
(20, 'Sandi yang cara membacanya sama dengan metode membaca aksara Arab, yaitu dibaca terbalik dari kanan ke kiri, disebut...', '["A. C","B. Rahasia","C. Sandi Arab","D. KIZNFPZ"]', 'C. Sandi Arab'),
(20, 'Sebuah pesan tertulis "AKUMARP", jika dipecahkan menggunakan kaidah Sandi Arab akan dapat dibaca menjadi kata...', '["A. PRAMUKA","B. 2 huruf","C. Sandi AN","D. Sandi Kotak 1"]', 'A. PRAMUKA'),
(20, 'Sandi yang cara membacanya memutar seperti cangkang kerang dari tengah ke luar atau luar ke dalam berlawanan jarum jam disebut...', '["A. A-N-I-B-M-E-P","B. Semaphore","C. Sandi Siput","D. Sandi Jam"]', 'C. Sandi Siput'),
(20, 'Sandi yang menggunakan titik-titik timbul untuk membantu penyandang tunanetra membaca, yang diciptakan di Prancis adalah...', '["A. Louis Braille","B. 08.05","C. Baris pertama","D. Sandi Arab"]', 'A. Louis Braille'),
(20, 'Susunan titik pada Sandi Braille dibentuk berdasarkan pola sebuah kotak imajiner yang berukuran...', '["A. 10 huruf tanpa ada huruf ganda yang sama","B. 2 kolom dan 3 baris (total 6 titik posisi)","C. Belah ketupat (segi empat silang)","D. MERAH PUTIH"]', 'B. 2 kolom dan 3 baris (total 6 titik posisi)'),
(20, 'Isyarat komunikasi jarak jauh yang menggunakan peraga sepasang bendera tangan dan sering masuk dalam materi wawasan komunikasi Pramuka disebut...', '["A. Tanpa titik","B. Sandi Kimia","C. Baris pertama","D. Semaphore"]', 'D. Semaphore'),
(20, 'Ukuran standar bendera Semaphore yang biasa digunakan oleh Pramuka Penggalang adalah persegi dengan ukuran...', '["A. 45 x 45 cm","B. Tanda Garis (-) pada Morse","C. Sandi Morse","D. Sandi Siput"]', 'A. 45 x 45 cm'),
(20, 'Warna standar untuk bendera Semaphore agar mudah terlihat dari jarak jauh adalah perpaduan menyilang dari warna...', '["A. 07.10","B. Merah dan Kuning","C. Sandi Jam","D. Louis Braille"]', 'B. Merah dan Kuning'),
(20, 'Dalam Sandi Kotak 1, huruf "Z" digambarkan menempati kerangka silang (X) pada sudut bawah dengan ditambahkan...', '["A. 6 titik","B. 5 titik","C. 1 titik","D. 3 titik"]', 'C. 1 titik'),
(20, 'Sandi yang memanipulasi abjad Morse ke dalam bentuk angka pembilang dan penyebut pecahan matematika disebut...', '["A. Sandi Pecahan / Sandi Matematika","B. Sandi AZ / Sandi Balik Abjad","C. Tanda Garis (-) pada Morse","D. Sir Arthur Conan Doyle (Sherlock Holmes)"]', 'A. Sandi Pecahan / Sandi Matematika'),
(20, 'Pada variasi Sandi Angka, jika disepakati A=3, B=4, maka huruf D akan ditulis menggunakan angka...', '["A. 4","B. 6","C. 3","D. 7"]', 'B. 6'),
(20, 'Huruf "E" dalam kode morse hanya terdiri dari satu titik. Dalam Sandi Kimia, huruf E dapat diwakilkan cukup dengan satu huruf saja, misalnya...', '["A. Huruf Vokal, contohnya O","B. Sandi Siput","C. Sandi Ular / Sandi Gergaji","D. Sandi AND"]', 'A. Huruf Vokal, contohnya O'),
(20, 'Huruf "T" dalam kode morse hanya terdiri dari satu garis. Dalam Sandi Kimia, huruf T dapat diwakilkan cukup dengan satu huruf, misalnya...', '["A. Baris pertama","B. Huruf Konsonan, contohnya K","C. Sandi Morse","D. 2 huruf"]', 'B. Huruf Konsonan, contohnya K'),
(20, 'Syarat utama dua buah kata yang akan dijadikan kunci dalam tabel baris/kolom Sandi Koordinat adalah gabungan katanya harus terdiri dari...', '["A. Sir Arthur Conan Doyle (Sherlock Holmes)","B. Palang tegak lurus dan silang (X)","C. 10 huruf tanpa ada huruf ganda yang sama","D. 2 kolom dan 3 baris (total 6 titik posisi)"]', 'C. 10 huruf tanpa ada huruf ganda yang sama'),
(20, 'Kata "Sandi" itu sendiri berarti...', '["A. OH","B. Rahasia","C. MERAH PUTIH","D. Sandi Arab"]', 'B. Rahasia'),
(20, 'Tujuan asli dibentuknya sandi atau kriptografi pada zaman dahulu yang menginspirasi kepramukaan adalah...', '["A. Mengirim pesan rahasia di masa perang/kritis agar tidak dapat dibaca oleh pihak musuh","B. Setiap kotak pada Sandi Kotak 2 berisi 3 huruf dan maksimal menggunakan 2 titik","C. 2","D. Tanpa titik"]', 'A. Mengirim pesan rahasia di masa perang/kritis agar tidak dapat dibaca oleh pihak musuh'),
(20, 'Jika Sandi Jam dimulai pukul 10.00 = A, dan beda waktu intervalnya dinaikkan menjadi 10 menit, maka pukul 10.20 menunjukkan huruf...', '["A. PRAMUKA","B. Sandi AN","C. C","D. Rahasia"]', 'C. C'),
(20, 'Sandi rahasia unik yang menggunakan bentuk gambar tongkat orang menari dengan posisi lengan berbeda-beda (Dancing Men) terinspirasi dari novel karya...', '["A. Sir Arthur Conan Doyle (Sherlock Holmes)","B. Belah ketupat (segi empat silang)","C. 10 huruf tanpa ada huruf ganda yang sama","D. Tanda Titik (.) pada Morse"]', 'A. Sir Arthur Conan Doyle (Sherlock Holmes)'),
(20, '"P-E-M-B-I-N-A" jika ditulis menggunakan rumus Sandi Arab akan menjadi susunan...', '["A. KIZNFPZ","B. A-N-I-B-M-E-P","C. Sandi Koordinat","D. 2 huruf"]', 'B. A-N-I-B-M-E-P'),
(20, 'Salah satu Syarat Kecakapan Umum (SKU) Pramuka Penggalang mewajibkan anggotanya untuk dapat memahami, membaca, dan mengirimkan pesan isyarat dasar yaitu...', '["A. 45 x 45 cm","B. Belah ketupat (segi empat silang)","C. Morse dan Semaphore","D. Sandi Siput"]', 'C. Morse dan Semaphore'),

-- ==========================================
-- BAB 24: P3K & Kesehatan
-- ==========================================
(24, 'Singkatan dari P3K adalah...', '["A. 2-4 orang","B. Pertolongan Pertama Pada Kecelakaan","C. Manuver Heimlich (hentakan pada perut)","D. Belakang (berlawanan arah jalan)"]', 'B. Pertolongan Pertama Pada Kecelakaan'),
(24, 'Tujuan utama dari pemberian P3K adalah...', '["A. Manuver Heimlich (hentakan pada perut)","B. Menyelamatkan nyawa dan mencegah kondisi korban memburuk","C. Tenang, Cepat, Tepat, dan Tidak Panik","D. 50-100 cm (agar tidak dibongkar hewan)"]', 'B. Menyelamatkan nyawa dan mencegah kondisi korban memburuk'),
(24, 'Langkah pertama yang harus dilakukan saat menemukan korban kecelakaan adalah...', '["A. Menundukkan kepala ke depan dan menjepit cuping hidung","B. Memastikan keamanan penolong, lokasi, dan korban (Aman Diri)","C. Mencoba meluruskan posisi tulang secara paksa","D. Tenang, Cepat, Tepat, dan Tidak Panik"]', 'B. Memastikan keamanan penolong, lokasi, dan korban (Aman Diri)'),
(24, 'Pembalut segitiga yang sangat sering digunakan dalam P3K Pramuka disebut...', '["A. Tandu Darurat (Dragbar)","B. Simpul Mati","C. Mitela","D. 2-4 orang"]', 'C. Mitela'),
(24, 'Alat keras/kaku yang digunakan untuk menahan tulang yang patah agar tidak bergerak disebut...', '["A. Segitiga terbuka","B. Bidai / Spalk","C. Simpul Mati","D. Minimal melewati dua sendi"]', 'B. Bidai / Spalk'),
(24, 'Pertolongan pertama pada korban mimisan yang benar adalah...', '["A. Menutup luka agar tidak infeksi dan menyerap darah","B. Menundukkan kepala ke depan dan menjepit cuping hidung","C. Mencegah kulit korban terluka saat menggunting perban","D. Imobilisasi (tidak menggerakkan bagian yang digigit) dan bawa ke RS"]', 'B. Menundukkan kepala ke depan dan menjepit cuping hidung'),
(24, 'Pendarahan arteri ditandai dengan ciri-ciri...', '["A. Dialiri air bersih mengalir selama 10-15 menit","B. Darah memancar seirama denyut jantung dan berwarna merah terang","C. Mencegah kulit korban terluka saat menggunting perban","D. Nadi cepat dan lemah, kulit pucat, keringat dingin"]', 'B. Darah memancar seirama denyut jantung dan berwarna merah terang'),
(24, 'Cara menghentikan pendarahan luar yang paling efektif adalah dengan teknik...', '["A. Balut tekan (tekan langsung di atas luka)","B. Perilaku Hidup Bersih dan Sehat (PHBS)","C. Lebih tinggi dari kepala (Elevasi)","D. Henti napas dan henti jantung"]', 'A. Balut tekan (tekan langsung di atas luka)'),
(24, 'Simpul yang digunakan untuk mengakhiri balutan mitela agar mudah dilepas adalah...', '["A. Luka Memar (Contusio)","B. Simpul Mati","C. Diare","D. Belakang (berlawanan arah jalan)"]', 'B. Simpul Mati'),
(24, 'Kondisi penurunan suhu tubuh secara drastis akibat cuaca dingin di gunung disebut...', '["A. Demam Berdarah (Dengue)","B. Hipotermia","C. Segitiga terbuka","D. Simpul Mati"]', 'B. Hipotermia'),
(24, 'Pertolongan pertama pada luka bakar ringan (derajat 1) adalah...', '["A. Henti napas dan henti jantung","B. Dialiri air bersih mengalir selama 10-15 menit","C. Perilaku Hidup Bersih dan Sehat (PHBS)","D. Menundukkan kepala ke depan dan menjepit cuping hidung"]', 'B. Dialiri air bersih mengalir selama 10-15 menit'),
(24, 'Alat untuk mengangkut korban kecelakaan secara darurat yang dibuat dari dua tongkat dan tali disebut...', '["A. Lengan / Bahu","B. Tandu Darurat (Dragbar)","C. Termometer","D. Pinset dan air bersih"]', 'B. Tandu Darurat (Dragbar)'),
(24, 'Jumlah ikatan minimal pada pemasangan bidai untuk patah tulang tungkai bawah adalah...', '["A. Air bersih / Boorwater","B. Luka Memar (Contusio)","C. Minyak Kayu Putih / Kaladin","D. Minimal melewati dua sendi"]', 'D. Minimal melewati dua sendi'),
(24, 'Korban pingsan sebaiknya diposisikan telentang dengan posisi kaki...', '["A. Tandu Darurat (Dragbar)","B. Henti napas dan henti jantung","C. Lebih tinggi dari kepala (Elevasi)","D. 50-100 cm (agar tidak dibongkar hewan)"]', 'C. Lebih tinggi dari kepala (Elevasi)'),
(24, 'Isi kotak P3K yang berfungsi untuk membersihkan luka dari kuman adalah...', '["A. Simpul Mati","B. Antiseptik (Betadine/Rivanol)","C. 36-37 derajat","D. Lengan / Bahu"]', 'B. Antiseptik (Betadine/Rivanol)'),
(24, 'Penyakit yang disebabkan oleh gigitan nyamuk Aedes Aegypti adalah...', '["A. Henti napas dan henti jantung","B. Demam Berdarah (Dengue)","C. 2-4 orang","D. Diare"]', 'B. Demam Berdarah (Dengue)'),
(24, 'Cara menangani kaki yang terkilir (kram/keseleo) dengan metode RICE, singkatan dari...', '["A. Antiseptik (Betadine/Rivanol)","B. Rest, Ice, Compression, Elevation","C. Luka Memar (Contusio)","D. Tandu Darurat (Dragbar)"]', 'B. Rest, Ice, Compression, Elevation'),
(24, 'Pertolongan pertama jika seseorang tersedak makanan dan sulit bernapas adalah dengan...', '["A. Mencegah kulit korban terluka saat menggunting perban","B. Manuver Heimlich (hentakan pada perut)","C. Pertolongan Pertama Pada Kecelakaan","D. Tenang, Cepat, Tepat, dan Tidak Panik"]', 'B. Manuver Heimlich (hentakan pada perut)'),
(24, 'Obat yang digunakan untuk mengurangi rasa sakit kepala atau demam ringan adalah...', '["A. Demam Berdarah (Dengue)","B. Parasetamol","C. Hipotermia","D. Gunting"]', 'B. Parasetamol'),
(24, 'Untuk mengganti cairan tubuh yang hilang akibat diare, sebaiknya diberikan...', '["A. Antasida","B. Oralit","C. 36-37 derajat","D. Gunting"]', 'B. Oralit'),
(24, 'Pembalutan pada luka di kepala biasanya menggunakan mitela yang dilipat menjadi bentuk...', '["A. 2-4 orang","B. Segitiga terbuka","C. Simpul Mati","D. 36-37 derajat"]', 'B. Segitiga terbuka'),
(24, 'Luka yang disebabkan oleh benda tumpul dan menyebabkan memar kebiruan disebut luka...', '["A. Air bersih / Boorwater","B. Luka Memar (Contusio)","C. Oralit","D. Hipotermia"]', 'B. Luka Memar (Contusio)'),
(24, 'Tindakan RJP (Resusitasi Jantung Paru) dilakukan pada korban yang...', '["A. Rest, Ice, Compression, Elevation","B. Henti napas dan henti jantung","C. Perilaku Hidup Bersih dan Sehat (PHBS)","D. Mencoba meluruskan posisi tulang secara paksa"]', 'B. Henti napas dan henti jantung'),
(24, 'Pada saat memindahkan korban dengan tandu, posisi kepala korban sebaiknya berada di...', '["A. Minimal melewati dua sendi","B. Belakang (berlawanan arah jalan)","C. Balutan angka delapan","D. Antiseptik (Betadine/Rivanol)"]', 'B. Belakang (berlawanan arah jalan)'),
(24, 'Warna kotak P3K standar biasanya adalah...', '["A. Luka Memar (Contusio)","B. Putih dengan tanda palang merah/hijau","C. Terkilir / Cedera sendi","D. Minimal melewati dua sendi"]', 'B. Putih dengan tanda palang merah/hijau'),
(24, 'Pertolongan pertama pada gigitan ular yang paling tepat adalah...', '["A. Nadi cepat dan lemah, kulit pucat, keringat dingin","B. Menundukkan kepala ke depan dan menjepit cuping hidung","C. Imobilisasi (tidak menggerakkan bagian yang digigit) dan bawa ke RS","D. Menutup luka agar tidak infeksi dan menyerap darah"]', 'C. Imobilisasi (tidak menggerakkan bagian yang digigit) dan bawa ke RS'),
(24, 'Pembalut elastis (Elastic Bandage) sangat baik digunakan untuk menangani...', '["A. Manuver Heimlich (hentakan pada perut)","B. Terkilir / Cedera sendi","C. Segitiga terbuka","D. Gigitan hewan (anjing/kucing) untuk cegah rabies"]', 'B. Terkilir / Cedera sendi'),
(24, 'Penyakit yang sering muncul di perkemahan akibat sanitasi buruk dan air kotor adalah...', '["A. 2-4 orang","B. Diare","C. Segitiga terbuka","D. Hipotermia"]', 'B. Diare'),
(24, 'Kasa steril diletakkan langsung di atas luka bertujuan untuk...', '["A. Darah memancar seirama denyut jantung dan berwarna merah terang","B. Menutup luka agar tidak infeksi dan menyerap darah","C. Balut tekan (tekan langsung di atas luka)","D. Menyelamatkan nyawa dan mencegah kondisi korban memburuk"]', 'B. Menutup luka agar tidak infeksi dan menyerap darah'),
(24, 'Berapa jumlah penolong yang ideal untuk mengangkat tandu darurat?', '["A. Termometer","B. 2-4 orang","C. Rest, Ice, Compression, Elevation","D. Air bersih / Boorwater"]', 'B. 2-4 orang'),
(24, 'Alat untuk mengukur suhu tubuh manusia disebut...', '["A. 2-4 orang","B. Termometer","C. Mitela","D. Diare"]', 'B. Termometer'),
(24, 'Suhu tubuh normal manusia berkisar antara...', '["A. 30 : 2","B. 36-37 derajat","C. Lengan / Bahu","D. Luka Memar (Contusio)"]', 'B. 36-37 derajat'),
(24, 'Tindakan yang harus dihindari saat menolong korban patah tulang adalah...', '["A. Air bersih / Boorwater","B. Mencoba meluruskan posisi tulang secara paksa","C. 50-100 cm (agar tidak dibongkar hewan)","D. Minyak Kayu Putih / Kaladin"]', 'B. Mencoba meluruskan posisi tulang secara paksa'),
(24, 'Mencuci tangan sebelum makan dan setelah beraktivitas merupakan contoh...', '["A. Mencoba meluruskan posisi tulang secara paksa","B. Perilaku Hidup Bersih dan Sehat (PHBS)","C. Mencegah kulit korban terluka saat menggunting perban","D. Minimal melewati dua sendi"]', 'B. Perilaku Hidup Bersih dan Sehat (PHBS)'),
(24, 'Cairan yang digunakan untuk mencuci mata jika kemasukan debu adalah...', '["A. 36-37 derajat","B. Air bersih / Boorwater","C. Perilaku Hidup Bersih dan Sehat (PHBS)","D. Segitiga terbuka"]', 'B. Air bersih / Boorwater'),
(24, 'Pembalut Mitela dilipat menjadi "Gendongan" berfungsi untuk menyangga cedera pada...', '["A. Diare","B. Lengan / Bahu","C. Pinset dan air bersih","D. Gunting"]', 'B. Lengan / Bahu'),
(24, 'Tanda-tanda seseorang mengalami syok (shock) adalah...', '["A. Balut tekan (tekan langsung di atas luka)","B. Nadi cepat dan lemah, kulit pucat, keringat dingin","C. Mencegah kulit korban terluka saat menggunting perban","D. Menyelamatkan nyawa dan mencegah kondisi korban memburuk"]', 'B. Nadi cepat dan lemah, kulit pucat, keringat dingin'),
(24, 'Zat racun dalam makanan dapat dinetralkan sementara (sebelum ke dokter) dengan meminum...', '["A. Susu / Air kelapa","B. Antiseptik (Betadine/Rivanol)","C. Gigitan hewan (anjing/kucing) untuk cegah rabies","D. Rest, Ice, Compression, Elevation"]', 'A. Susu / Air kelapa'),
(24, 'Obat luar yang digunakan untuk meredakan gatal akibat gigitan serangga adalah...', '["A. Manuver Heimlich (hentakan pada perut)","B. Minyak Kayu Putih / Kaladin","C. Menyelamatkan nyawa dan mencegah kondisi korban memburuk","D. Bidai / Spalk"]', 'B. Minyak Kayu Putih / Kaladin'),
(24, 'Luka tusuk akibat paku berkarat sangat berisiko menyebabkan penyakit...', '["A. Demam Berdarah (Dengue)","B. Tetanus","C. Antiseptik (Betadine/Rivanol)","D. Balutan angka delapan"]', 'B. Tetanus'),
(24, 'Pada RJP (CPR), rasio kompresi dada dan napas buatan untuk satu penolong adalah...', '["A. Minimal melewati dua sendi","B. 30 : 2","C. Air bersih / Boorwater","D. Minyak Kayu Putih / Kaladin"]', 'B. 30 : 2'),
(24, 'Pembalutan luka di lutut yang sedang ditekuk paling baik menggunakan teknik...', '["A. Balutan angka delapan","B. Tandu Darurat (Dragbar)","C. Oralit","D. Terkilir / Cedera sendi"]', 'A. Balutan angka delapan'),
(24, 'Bagian dari tas P3K yang digunakan untuk memotong perban atau pakaian korban adalah...', '["A. Parasetamol","B. Gunting","C. Termometer","D. 36-37 derajat"]', 'B. Gunting'),
(24, 'Untuk membersihkan luka yang kotor dari kerikil atau pasir digunakan...', '["A. Demam Berdarah (Dengue)","B. Pinset dan air bersih","C. Terkilir / Cedera sendi","D. Lengan / Bahu"]', 'B. Pinset dan air bersih'),
(24, 'Apa yang harus dilakukan jika korban tersambar petir?', '["A. Imobilisasi (tidak menggerakkan bagian yang digigit) dan bawa ke RS","B. Segera periksa napas dan nadi, lakukan RJP jika perlu, dan bawa ke RS","C. Bidai / Spalk","D. Demam Berdarah (Dengue)"]', 'B. Segera periksa napas dan nadi, lakukan RJP jika perlu, dan bawa ke RS'),
(24, 'Gunting yang bagian ujungnya tumpul (Gunting Verban) bertujuan untuk...', '["A. Lebih tinggi dari kepala (Elevasi)","B. Mencegah kulit korban terluka saat menggunting perban","C. Perilaku Hidup Bersih dan Sehat (PHBS)","D. Nadi cepat dan lemah, kulit pucat, keringat dingin"]', 'B. Mencegah kulit korban terluka saat menggunting perban'),
(24, 'Kesehatan lingkungan perkemahan dijaga dengan cara membuat lubang sampah sedalam...', '["A. Lebih tinggi dari kepala (Elevasi)","B. 50-100 cm (agar tidak dibongkar hewan)","C. Susu / Air kelapa","D. Mencegah kulit korban terluka saat menggunting perban"]', 'B. 50-100 cm (agar tidak dibongkar hewan)'),
(24, 'Obat yang digunakan untuk menolong sakit perut akibat maag adalah...', '["A. Termometer","B. Antasida","C. Simpul Mati","D. Hipotermia"]', 'B. Antasida'),
(24, 'Mencuci luka dengan air sabun sangat disarankan khusus untuk luka akibat...', '["A. Nadi cepat dan lemah, kulit pucat, keringat dingin","B. Gigitan hewan (anjing/kucing) untuk cegah rabies","C. Manuver Heimlich (hentakan pada perut)","D. Susu / Air kelapa"]', 'B. Gigitan hewan (anjing/kucing) untuk cegah rabies'),
(24, 'Prinsip utama penolong P3K adalah...', '["A. Terkilir / Cedera sendi","B. Tenang, Cepat, Tepat, dan Tidak Panik","C. Balut tekan (tekan langsung di atas luka)","D. Pinset dan air bersih"]', 'B. Tenang, Cepat, Tepat, dan Tidak Panik'),

-- ==========================================
-- BAB 99: Tambahan / Campuran
-- ==========================================
(99, 'Gerakan kepanduan di Indonesia resmi diakui dan menjadi anggota WOSM (World Organization of the Scout Movement) pada tahun...', '["A. 1951","B. 1953","C. 1950","D. 1955"]', 'B. 1953'),
(99, 'Sifat kepramukaan yang berarti penyelenggaraannya disesuaikan dengan keadaan, kebutuhan, dan kepentingan masyarakat di negaranya adalah sifat...', '["A. Dinizulu","B. Nasional","C. AR (.-.-.)","D. 13th Hussars"]', 'B. Nasional'),
(99, 'Semboyan Sistem Among "Ing Madyo Mangun Karso" memiliki arti seorang Pembina harus mampu...', '["A. Cerita Api Unggun (Campfire Yarns)","B. Di tengah membangun kemauan/semangat","C. Baris M, Kolom P","D. 15 - 20 meter"]', 'B. Di tengah membangun kemauan/semangat'),
(99, 'Tanda Kecakapan Khusus (TKK) tingkat tertinggi yang bentuknya segilima beraturan adalah tingkat...', '["A. Ketiga","B. --.- dan .--.","C. Utama","D. 13th Hussars"]', 'C. Utama'),
(99, 'Undang-Undang Republik Indonesia yang secara khusus mengatur tentang Gerakan Pramuka saat ini adalah...', '["A. Rest, Ice, Compression, Elevation","B. UU No. 12 Tahun 2010","C. 15 - 20 meter","D. Serigala yang tidak pernah tidur"]', 'B. UU No. 12 Tahun 2010'),
(99, 'Bapak Pandu Dunia (Chief Scout of the World) dan Bapak Pramuka Indonesia secara berurutan adalah...', '["A. Membebat cedera persendian (terkilir/keseleo) agar tidak bengkak","B. Serigala yang tidak pernah tidur","C. Baden Powell dan Sri Sultan Hamengkubuwono IX","D. 30 kompresi : 2 napas"]', 'C. Baden Powell dan Sri Sultan Hamengkubuwono IX'),
(99, 'Penggolongan usia Pramuka Penegak yang tepat adalah...', '["A. Di tengah membangun kemauan/semangat","B. AR (.-.-.)","C. 16 - 20 tahun","D. Simpul Tali Tenda (Taut-line Hitch)"]', 'C. 16 - 20 tahun'),
(99, 'Meskipun lekat dengan dunia militer, ayah dari Baden-Powell sejatinya adalah seorang...', '["A. Lembah atau aliran air","B. Guru Besar Geometri di Universitas Oxford","C. Baris M, Kolom P","D. Simpul Anyam (Sheet Bend)"]', 'B. Guru Besar Geometri di Universitas Oxford'),
(99, 'Suku-suku di Afrika memberikan julukan "Impeesa" kepada Baden-Powell, yang memiliki makna filosofis...', '["A. Rovering to Success","B. Baden Powell dan Sri Sultan Hamengkubuwono IX","C. Serigala yang tidak pernah tidur","D. Santo George (St. George)"]', 'C. Serigala yang tidak pernah tidur'),
(99, 'Buku mahakarya Baden-Powell yang ditujukan khusus untuk golongan pemuda (Rover Scout) pada tahun 1922 berjudul...', '["A. Simpul Tali Tenda (Taut-line Hitch)","B. Nasional","C. Baris M, Kolom P","D. Rovering to Success"]', 'D. Rovering to Success'),
(99, 'Kalung manik-manik kayu (Wood Badge) yang dikalungkan pada Pembina Pramuka lulusan kursus lanjutan berasal dari kalung pimpinan suku Afrika bernama...', '["A. Rovering to Success","B. -.-.-","C. Dinizulu","D. Sandi Jam"]', 'C. Dinizulu'),
(99, 'Pada batu nisan makam Baden-Powell di Nyeri, Kenya, terdapat tanda jejak kepanduan berupa lingkaran dengan titik di tengah yang memiliki arti rahasia...', '["A. Curvimeter","B. Saya telah pulang","C. Tetanus","D. Santo George (St. George)"]', 'B. Saya telah pulang'),
(99, 'Pasukan kavaleri pertama yang ditempati Baden-Powell saat bertugas ke India dengan pangkat Pembantu Letnan adalah...', '["A. 16 - 20 tahun","B. AR (.-.-.)","C. 13th Hussars","D. P"]', 'C. 13th Hussars'),
(99, 'Buku Scouting for Boys secara struktural dibagi ke dalam 26 bab khusus yang oleh Baden-Powell disebut dengan istilah...', '["A. Lord Edward Cecil","B. Cerita Api Unggun (Campfire Yarns)","C. Guru Besar Geometri di Universitas Oxford","D. Baden Powell dan Sri Sultan Hamengkubuwono IX"]', 'B. Cerita Api Unggun (Campfire Yarns)'),
(99, 'Simpul yang paling tepat digunakan untuk menyambung dua utas tali yang ukurannya TIDAK SAMA besar dan dalam keadaan kering adalah...', '["A. Simpul Anyam (Sheet Bend)","B. Deklinasi Magnetis","C. 13th Hussars","D. 2 kilometer"]', 'A. Simpul Anyam (Sheet Bend)'),
(99, 'Prinsip konservasi dalam Cerita Api Unggun ke-15 melarang pandu membunuh binatang apa pun, KECUALI...', '["A. Menghapus semua rangkaian huruf A-N-D yang berdekatan","B. Terjebak banjir bandang jika hujan lebat turun di hulu","C. Ketika terancam bahaya keselamatan atau terpaksa untuk bertahan hidup","D. Baden Powell dan Sri Sultan Hamengkubuwono IX"]', 'C. Ketika terancam bahaya keselamatan atau terpaksa untuk bertahan hidup'),
(99, 'Tokoh orang suci pelindung Inggris yang dijadikan simbol ksatria kaum pandu di seluruh dunia (diperingati setiap 23 April) karena keberaniannya menumpas naga adalah...', '["A. Saya telah pulang","B. Santo George (St. George)","C. Rest, Ice, Compression, Elevation","D. 13th Hussars"]', 'B. Santo George (St. George)'),
(99, 'Tindakan yang Paling Tepat jika pakaian yang dikenakan tiba-tiba tersambar api menurut panduan P3K Scouting for Boys adalah...', '["A. Menundukkan kepala ke depan dan menjepit cuping hidung selama 10 menit","B. Terjebak banjir bandang jika hujan lebat turun di hulu","C. Berguling-guling di tanah atau membungkus rapat dengan selimut tebal","D. Baden Powell dan Sri Sultan Hamengkubuwono IX"]', 'C. Berguling-guling di tanah atau membungkus rapat dengan selimut tebal'),
(99, 'Inspirasi utama Baden-Powell tentang pentingnya pemuda bermula dari pasukan anak-anak saat pengepungan kota Mafeking yang dipimpin oleh...', '["A. 15 - 20 meter","B. Lord Edward Cecil","C. Saya telah pulang","D. -.-.-"]', 'B. Lord Edward Cecil'),
(99, 'Mendirikan tenda di dasar cekungan (lembah sempit kering) sangat dilarang oleh aturan perkemahan tingkat lanjut karena risiko...', '["A. 45-60 derajat berlawanan dengan arah tarikan tali tenda","B. Ketika terancam bahaya keselamatan atau terpaksa untuk bertahan hidup","C. Terjebak banjir bandang jika hujan lebat turun di hulu","D. Menundukkan kepala ke depan dan menjepit cuping hidung selama 10 menit"]', 'C. Terjebak banjir bandang jika hujan lebat turun di hulu'),
(99, 'Agar pasak tenda menancap kuat dan tidak mudah tercabut oleh angin, kemiringan pasak ke dalam tanah harus membentuk sudut...', '["A. Menghapus semua rangkaian huruf A-N-D yang berdekatan","B. 45-60 derajat berlawanan dengan arah tarikan tali tenda","C. Ketika terancam bahaya keselamatan atau terpaksa untuk bertahan hidup","D. Terjebak banjir bandang jika hujan lebat turun di hulu"]', 'B. 45-60 derajat berlawanan dengan arah tarikan tali tenda'),
(99, 'Celana berbahan Jeans/Denim dilarang keras dipakai untuk pendakian dan kemah alam bebas karena alasan medis, yaitu...', '["A. Baca garis vertikal dulu (Easting ke kanan), lalu garis horizontal (Northing ke atas)","B. Berat, menahan panas, dan sangat sulit kering jika basah sehingga memicu hipotermia","C. Karena zat tersebut menahan/memerangkap sisa panas di dalam kulit dan memicu infeksi hebat","D. Menundukkan kepala ke depan dan menjepit cuping hidung selama 10 menit"]', 'B. Berat, menahan panas, dan sangat sulit kering jika basah sehingga memicu hipotermia'),
(99, 'Penerapan prinsip "Pack it in, Pack it out" dalam manajemen sampah perkemahan berarti...', '["A. Menundukkan kepala ke depan dan menjepit cuping hidung selama 10 menit","B. Berat, menahan panas, dan sangat sulit kering jika basah sehingga memicu hipotermia","C. Membawa kembali turun semua sampah anorganik untuk dibuang ke tempat yang semestinya","D. Baca garis vertikal dulu (Easting ke kanan), lalu garis horizontal (Northing ke atas)"]', 'C. Membawa kembali turun semua sampah anorganik untuk dibuang ke tempat yang semestinya'),
(99, 'Simpul yang paling praktis untuk menautkan tali tenda pada pasak karena bisa ditarik ulur (dikencangkan/dikendurkan) tanpa melepas simpul adalah...', '["A. Guru Besar Geometri di Universitas Oxford","B. Simpul Tali Tenda (Taut-line Hitch)","C. Cerita Api Unggun (Campfire Yarns)","D. 30 kompresi : 2 napas"]', 'B. Simpul Tali Tenda (Taut-line Hitch)'),
(99, 'Jarak minimal yang direkomendasikan untuk membangun MCK (Mandi Cuci Kakus) darurat dari sumber mata air agar tidak mencemari lingkungan adalah...', '["A. 1 : 3","B. Simpul Anyam (Sheet Bend)","C. 15 - 20 meter","D. Sandi Jam"]', 'C. 15 - 20 meter'),
(99, 'Menurut standar telegrafi internasional, perbandingan durasi waktu antara ketukan "titik" (dot) dan "garis" (dash) dalam sandi Morse adalah...', '["A. -.-.","B. 1 : 3","C. Baris M, Kolom P","D. Santo George (St. George)"]', 'B. 1 : 3'),
(99, 'Isyarat prosedural (Prosign) standar internasional untuk "Attention" atau tanda memulai pesan Morse yang sah adalah...', '["A. -.-..","B. .-.-.","C. -.-.-","D. -..--"]', 'C. -.-.-'),
(99, 'Jika huruf "O" adalah (---) dan "S" adalah (...), maka huruf "C" dalam kode morse adalah...', '["A. -.-.","B. ..-.","C. ---.","D. -..-"]', 'A. -.-.'),
(99, 'Jika memecahkan kata menggunakan "Sandi AND", hal pertama yang harus dilakukan adalah...', '["A. 30 kompresi : 2 napas","B. Menghapus semua rangkaian huruf A-N-D yang berdekatan","C. Membebat cedera persendian (terkilir/keseleo) agar tidak bengkak","D. UU No. 12 Tahun 2010"]', 'B. Menghapus semua rangkaian huruf A-N-D yang berdekatan'),
(99, 'Huruf Q dan P dalam kode morse memiliki kombinasi garis yang mengecoh. Kombinasi yang benar secara berurutan untuk Q dan P adalah...', '["A. --.- dan .--.","B. Lembah atau aliran air","C. 1 : 3","D. Utama"]', 'A. --.- dan .--.'),
(99, 'Isyarat bahwa pesan telah selesai seluruhnya (End of Message) dikirimkan dengan sandi...', '["A. -.-.-","B. AR (.-.-.)","C. Baris M, Kolom P","D. Santo George (St. George)"]', 'B. AR (.-.-.)'),
(99, 'Jika membaca peta topografi berskala 1:50.000 dan jarak dua titik di peta adalah 4 cm, maka jarak sebenarnya di medan adalah...', '["A. 5 kilometer","B. 2 kilometer","C. 3 kilometer","D. 4 kilometer"]', 'B. 2 kilometer'),
(99, 'Garis kontur yang tergambar menjorok ke arah tempat yang lebih tinggi (membentuk huruf V terbalik) secara topografi merupakan...', '["A. Cerita Api Unggun (Campfire Yarns)","B. Lembah atau aliran air","C. Sandi Jam","D. Serigala yang tidak pernah tidur"]', 'B. Lembah atau aliran air'),
(99, 'Aturan baku "Golden Rule" dalam membaca koordinat Grid (UTM) 6 angka pada peta topografi adalah...', '["A. Baca garis vertikal dulu (Easting ke kanan), lalu garis horizontal (Northing ke atas)","B. Menundukkan kepala ke depan dan menjepit cuping hidung selama 10 menit","C. Berat, menahan panas, dan sangat sulit kering jika basah sehingga memicu hipotermia","D. Karena zat tersebut menahan/memerangkap sisa panas di dalam kulit dan memicu infeksi hebat"]', 'A. Baca garis vertikal dulu (Easting ke kanan), lalu garis horizontal (Northing ke atas)'),
(99, 'Perbedaan sudut putar yang ditunjukkan antara Utara Magnetis di jarum kompas dan Utara Peta (Grid) pada selembar peta disebut...', '["A. 1 : 3","B. AR (.-.-.)","C. Deklinasi Magnetis","D. Rovering to Success"]', 'C. Deklinasi Magnetis'),
(99, 'Alat mekanis dengan roda gigi kecil yang dijalankan menyusuri kelokan sungai di peta untuk menghitung jarak rute melengkung disebut...', '["A. AR (.-.-.)","B. Sandi Jam","C. Dinizulu","D. Curvimeter"]', 'D. Curvimeter'),
(99, 'Metode navigasi siang hari tanpa kompas menggunakan bayangan tongkat tegak lurus yang memanfaatkan pergerakan semu matahari disebut...', '["A. Guru Besar Geometri di Universitas Oxford","B. Sundial (Metode Bayangan Matahari)","C. Deklinasi Magnetis","D. UU No. 12 Tahun 2010"]', 'B. Sundial (Metode Bayangan Matahari)'),
(99, 'Dalam pemecahan Sandi Kotak 2, satu kotak kerangka silang dihuni oleh 3 huruf. Jika terdapat 2 titik di atas kerangka tersebut, maka itu menunjukkan huruf...', '["A. --.- dan .--.","B. Dinizulu","C. Ketiga","D. 1953"]', 'C. Ketiga'),
(99, 'Sandi Kimia mengonversi kode Morse ke huruf. Jika kode aslinya adalah "H2O" (H=konsonan, O=vokal), maka morse yang terbentuk adalah...', '["A. -..","B. .-.","C. --.","D. ..-"]', 'C. --.'),
(99, 'Sandi yang menggunakan patokan waktu dengan selisih yang konstan (misal pukul 08.00 = A, 08.05 = B, 08.10 = C) disebut...', '["A. 1953","B. AR (.-.-.)","C. Sandi Jam","D. Lord Edward Cecil"]', 'C. Sandi Jam'),
(99, 'Sandi AZ menukar huruf awal dengan huruf akhir alfabet. Jika sandinya berbunyi "K", maka huruf aslinya adalah...', '["A. 1953","B. P","C. Lord Edward Cecil","D. --.- dan .--."]', 'B. P'),
(99, 'Sandi yang bentuk fisiknya memanjang menyerupai gerigi atau gelombang naik turun tanpa spasi putus disebut...', '["A. Lord Edward Cecil","B. --.- dan .--.","C. Sandi Ular / Sandi Gergaji","D. UU No. 12 Tahun 2010"]', 'C. Sandi Ular / Sandi Gergaji'),
(99, 'Dalam Sandi Koordinat tabel 5x5 dengan kata kunci "MERAH PUTIH", huruf A terletak pada titik temu kordinat...', '["A. Baris M, Kolom P","B. Serigala yang tidak pernah tidur","C. Sundial (Metode Bayangan Matahari)","D. --.- dan .--."]', 'A. Baris M, Kolom P'),
(99, 'Tindakan Pertolongan Pertama yang BENAR pada korban kecelakaan yang mimisan (hidung berdarah) adalah...', '["A. Karena zat tersebut menahan/memerangkap sisa panas di dalam kulit dan memicu infeksi hebat","B. Berguling-guling di tanah atau membungkus rapat dengan selimut tebal","C. Menundukkan kepala ke depan dan menjepit cuping hidung selama 10 menit","D. Terjebak banjir bandang jika hujan lebat turun di hulu"]', 'C. Menundukkan kepala ke depan dan menjepit cuping hidung selama 10 menit'),
(99, 'Rasio kompresi dada (pijat jantung) dan bantuan napas buatan pada RJP (Resusitasi Jantung Paru) untuk 1 orang penolong menurut standar medis terbaru adalah...', '["A. Menghapus semua rangkaian huruf A-N-D yang berdekatan","B. 30 kompresi : 2 napas","C. Saya telah pulang","D. Membebat cedera persendian (terkilir/keseleo) agar tidak bengkak"]', 'B. 30 kompresi : 2 napas'),
(99, 'Penanganan keseleo (terkilir) di lapangan paling efektif menggunakan metode RICE, yang merupakan singkatan dari...', '["A. Rest, Ice, Compression, Elevation","B. 16 - 20 tahun","C. Sandi Ular / Sandi Gergaji","D. --.- dan .--."]', 'A. Rest, Ice, Compression, Elevation'),
(99, 'Alasan dilarangnya mengoleskan pasta gigi, mentega, atau kecap pada luka bakar melepuh adalah...', '["A. Baca garis vertikal dulu (Easting ke kanan), lalu garis horizontal (Northing ke atas)","B. Karena zat tersebut menahan/memerangkap sisa panas di dalam kulit dan memicu infeksi hebat","C. Menundukkan kepala ke depan dan menjepit cuping hidung selama 10 menit","D. Membawa kembali turun semua sampah anorganik untuk dibuang ke tempat yang semestinya"]', 'B. Karena zat tersebut menahan/memerangkap sisa panas di dalam kulit dan memicu infeksi hebat'),
(99, 'Jika digigit ular berbisa di tengah hutan, penanganan paling krusial sebelum di bawa ke RS adalah...', '["A. UU No. 12 Tahun 2010","B. Rest, Ice, Compression, Elevation","C. Imobilisasi (membidai area gigitan agar korban tidak bergerak sama sekali) untuk menahan laju penyebaran racun di kelenjar getah bening","D. -.-."]', 'C. Imobilisasi (membidai area gigitan agar korban tidak bergerak sama sekali) untuk menahan laju penyebaran racun di kelenjar getah bening'),
(99, 'Luka tusuk yang diakibatkan oleh benda kotor berkarat (seperti paku) sangat berisiko fatal jika tidak dicuci bersih karena membawa bakteri penyebab...', '["A. -.-.","B. Nasional","C. Tetanus","D. 1 : 3"]', 'C. Tetanus'),
(99, 'Pembalut elastis berwarna coklat (Elastic Bandage) sangat direkomendasikan berada di dalam kotak P3K Pramuka karena berfungsi spesifik untuk...', '["A. Baden Powell dan Sri Sultan Hamengkubuwono IX","B. Membebat cedera persendian (terkilir/keseleo) agar tidak bengkak","C. Berguling-guling di tanah atau membungkus rapat dengan selimut tebal","D. Sandi Ular / Sandi Gergaji"]', 'B. Membebat cedera persendian (terkilir/keseleo) agar tidak bengkak')